export const rand = (n) => Math.floor(Math.random() * n);
export const clamp = (n, min, max) => Math.max(min, Math.min(max, n));
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
export const chance = (p) => Math.random() < p;

export function shuffle(arr) {
  const copy = [...arr];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

export function weightedPick(entries) {
  const total = entries.reduce((sum, entry) => sum + entry.weight, 0);
  let roll = Math.random() * total;
  for (const entry of entries) {
    roll -= entry.weight;
    if (roll <= 0) return entry.value;
  }
  return entries[entries.length - 1].value;
}

export function roman(n) {
  return ["0", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"][n] || String(n);
}

export function signed(n) {
  return n >= 0 ? `+${n}` : `${n}`;
}

export function money(n) {
  return `${n}g`;
}

/* The main game shell: meta progression, runs, maps, and shared helpers. */

import {
  CHARACTERS, CHARACTER_IDS, META_UPGRADES, SAVE_KEY, mergeMeta,
  metaUpgradeCost, PRESTIGE_STYLES,
} from "./data/characters.js";
import { CARDS, cardPool } from "./data/cards.js";
import { CHARMS } from "./data/enemies.js";
import { EVENTS, SPECIALS } from "./data/events.js";
import { rand, pick, shuffle, weightedPick, clamp } from "./util.js";
import { worldMethods } from "./world.js";
import { combatMethods } from "./combat.js";

export class Game {
  constructor(meta) {
    this.meta = mergeMeta(meta);
    this.screen = "title";
    this.run = null;
    this.combat = null;
    this.pending = null;
    this.briefing = null;
    this.notice = null;
    this.onChange = () => {};
    this.uid = 1;
  }

  emit() {
    this.onChange();
  }

  saveMeta() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(this.meta));
    } catch {
      /* local storage is a luxury, not a requirement */
    }
  }

  setScreen(screen) {
    this.screen = screen;
    this.notice = null;
    this.emit();
  }

  goTitle() {
    this.pending = null;
    this.combat = null;
    this.run = null;
    this.setScreen("title");
  }

  openSelect() {
    this.setScreen("select");
  }

  openBriefing(charId) {
    const unlocked = this.meta.unlocks[charId] || 0;
    this.briefing = { charId, outfit: Math.min(this.meta.outfit[charId] || 0, unlocked) };
    this.setScreen("briefing");
  }

  selectBriefingOutfit(tier) {
    if (!this.briefing) return;
    if (tier > (this.meta.unlocks[this.briefing.charId] || 0)) return;
    this.briefing.outfit = tier;
    this.emit();
  }

  openArchive() {
    this.setScreen("archive");
  }

  openWardrobe() {
    this.setScreen("wardrobe");
  }

  openTips() {
    this.setScreen("tips");
  }

  equipOutfit(charId, tier) {
    if (tier > (this.meta.unlocks[charId] || 0)) return;
    this.meta.outfit[charId] = tier;
    this.saveMeta();
    this.notice = { text: `Outfit equipped: ${CHARACTERS[charId].outfits[tier].name}.`, tone: "good" };
    this.emit();
  }

  upgradeCost(upgradeId) {
    const up = META_UPGRADES.find((u) => u.id === upgradeId);
    if (!up) return 0;
    return metaUpgradeCost(up, this.meta.upgrades[upgradeId] || 0);
  }

  buyUpgrade(upgradeId) {
    const up = META_UPGRADES.find((u) => u.id === upgradeId);
    const level = this.meta.upgrades[upgradeId] || 0;
    if (!up || level >= up.max) return;
    const cost = metaUpgradeCost(up, level);
    if (this.meta.ash < cost) {
      this.notice = { text: "Not enough Ash.", tone: "bad" };
      this.emit();
      return;
    }
    this.meta.ash -= cost;
    this.meta.upgrades[upgradeId] = level + 1;
    this.saveMeta();
    this.notice = { text: `${up.name} restored to rank ${level + 1}.`, tone: "good" };
    this.emit();
  }

  canPrestige() {
    return this.meta.prestige < 3 && this.meta.runs > 0;
  }

  prestige() {
    if (!this.canPrestige()) return;
    const next = this.meta.prestige + 1;
    for (const id of CHARACTER_IDS) {
      this.meta.unlocks[id] = Math.max(this.meta.unlocks[id] || 0, next);
      this.meta.outfit[id] = next;
    }
    this.meta.prestige = next;
    this.meta.ash = 0;
    this.meta.upgrades = { vitality: 0, edge: 0, fortune: 0, instinct: 0, endurance: 0, insight: 0 };
    this.meta.runs = 0;
    this.meta.clears = 0;
    this.meta.bestAct = 0;
    this.meta.bossKills = 0;
    this.run = null;
    this.combat = null;
    this.pending = { prestige: next };
    this.saveMeta();
    this.screen = "prestige";
    this.emit();
  }

  beginRun() {
    if (!this.briefing) return;
    const charId = this.briefing.charId;
    const def = CHARACTERS[charId];
    const tier = Math.min(this.briefing.outfit, this.meta.unlocks[charId] || 0);
    this.meta.outfit[charId] = tier;
    this.saveMeta();

    const hp = def.hp + (this.meta.upgrades.vitality || 0) * 5;
    const map = this.generateMap(1);
    const startNode = map.nodes.find((n) => n.type === "start");
    this.run = {
      char: charId,
      outfit: tier,
      act: 1,
      hp,
      maxHp: hp,
      gold: 20 + (this.meta.upgrades.fortune || 0) * 15,
      strength: this.meta.upgrades.edge || 0,
      crit: def.crit + (this.meta.upgrades.instinct || 0) * 0.04,
      critDamage: def.critDamage,
      staminaMax: def.stamina + (this.meta.upgrades.endurance || 0),
      drawCount: def.draw + (this.meta.upgrades.insight || 0),
      tacoMax: 0,
      tacoAttack: 0,
      deck: def.starter.map((key) => this.makeCard(key)),
      charms: [],
      boons: [],
      seenEvents: [],
      roomsCleared: 0,
      battlesWon: 0,
      map,
      currentNode: startNode.id,
      currentRow: 0,
      available: this.availableFrom(startNode, map).map((n) => n.id),
    };
    this.combat = null;
    this.pending = null;
    this.screen = "map";
    this.emit();
  }

  /* ---------------- cards ---------------- */

  makeCard(key, upgraded = false) {
    return { key, uid: `c${this.uid++}`, upgraded };
  }

  addCard(key, upgraded = false) {
    if (!this.run) return null;
    const card = this.makeCard(key, upgraded);
    this.run.deck.push(card);
    return card;
  }

  removeCard(uid) {
    if (!this.run) return false;
    const index = this.run.deck.findIndex((c) => c.uid === uid);
    if (index < 0) return false;
    this.run.deck.splice(index, 1);
    return true;
  }

  upgradeCard(uid) {
    const card = this.run?.deck.find((c) => c.uid === uid);
    if (!card || card.upgraded) return false;
    card.upgraded = true;
    return true;
  }

  randomCardKey(rarity = "common") {
    if (!this.run) return null;
    let pool = cardPool(this.run.char, [rarity]);
    if (!pool.length) pool = cardPool(this.run.char);
    return pick(pool);
  }

  awardCharm(key) {
    if (!this.run || !key) return null;
    if (this.run.charms.includes(key)) return null;
    this.run.charms.push(key);
    const charm = CHARMS[key];
    if (charm?.onAcquire) charm.onAcquire({ run: this.run, game: this });
    return charm;
  }

  randomAvailableCharm() {
    const pool = Object.keys(CHARMS).filter((key) => !this.run.charms.includes(key));
    return pool.length ? pick(pool) : null;
  }

  applySpec(spec = {}) {
    const run = this.run;
    const lines = [];
    if (!run) return lines;

    if (spec.gold) {
      run.gold = Math.max(0, run.gold + spec.gold);
      lines.push(`${spec.gold > 0 ? "Gain" : "Lose"} ${Math.abs(spec.gold)} gold.`);
    }
    if (spec.hp) {
      run.hp = Math.max(1, Math.min(run.maxHp, run.hp + spec.hp));
      lines.push(`${spec.hp > 0 ? "Heal" : "Lose"} ${Math.abs(spec.hp)} HP.`);
    }
    if (spec.heal) {
      run.hp = Math.min(run.maxHp, run.hp + spec.heal);
      lines.push(`Heal ${spec.heal} HP.`);
    }
    if (spec.healPct) {
      const amount = Math.ceil(run.maxHp * spec.healPct);
      run.hp = Math.min(run.maxHp, run.hp + amount);
      lines.push(`Heal ${amount} HP.`);
    }
    if (spec.maxHp) {
      run.maxHp = Math.max(10, run.maxHp + spec.maxHp);
      run.hp = Math.min(run.hp, run.maxHp);
      lines.push(`${spec.maxHp > 0 ? "Gain" : "Lose"} ${Math.abs(spec.maxHp)} max HP.`);
    }
    if (spec.strength) {
      run.strength = Math.max(0, run.strength + spec.strength);
      lines.push(`${spec.strength > 0 ? "Gain" : "Lose"} ${Math.abs(spec.strength)} Strength.`);
    }
    if (spec.crit) {
      run.crit = clamp(run.crit + spec.crit, 0, 0.75);
      lines.push(`Gain ${Math.round(spec.crit * 100)}% Crit.`);
    }
    if (spec.drawBonus) {
      run.drawCount += spec.drawBonus;
      lines.push(`Draw +${spec.drawBonus} card each turn.`);
    }
    if (spec.staminaBonus) {
      run.staminaMax += spec.staminaBonus;
      lines.push(`Gain +${spec.staminaBonus} max Stamina.`);
    }
    if (spec.tacoMax) {
      run.tacoMax += spec.tacoMax;
      lines.push(`Taco gains +${spec.tacoMax} max HP.`);
    }
    if (spec.tacoAttack) {
      run.tacoAttack += spec.tacoAttack;
      lines.push(`Taco gains +${spec.tacoAttack} bite damage.`);
    }
    if (spec.randomCard) {
      const key = this.randomCardKey(spec.randomCard);
      if (key) {
        this.addCard(key);
        lines.push(`Gained ${CARDS[key].name} (${spec.randomCard}).`);
      }
    }
    if (spec.randomCard2) {
      const key = this.randomCardKey(spec.randomCard2);
      if (key) {
        this.addCard(key);
        lines.push(`Gained ${CARDS[key].name} (${spec.randomCard2}).`);
      }
    }
    if (spec.randomUpgrade) {
      const candidates = run.deck.filter((c) => !c.upgraded);
      shuffle(candidates);
      const chosen = candidates.slice(0, spec.randomUpgrade);
      for (const card of chosen) {
        card.upgraded = true;
        lines.push(`Upgraded ${CARDS[card.key].name}.`);
      }
      if (!chosen.length) lines.push("Nothing left to upgrade.");
    }
    if (spec.randomCharm) {
      const key = this.randomAvailableCharm();
      if (key) {
        this.awardCharm(key);
        lines.push(`Gained charm: ${CHARMS[key].name}.`);
      } else {
        run.gold += 50;
        lines.push("All charms collected. Gained 50 gold instead.");
      }
    }
    if (spec.removeRandomCards) {
      const removable = [...run.deck];
      shuffle(removable);
      const removed = removable.slice(0, Math.min(spec.removeRandomCards, Math.max(0, run.deck.length - 4)));
      for (const card of removed) {
        this.removeCard(card.uid);
        lines.push(`Removed ${CARDS[card.key].name}.`);
      }
    }
    return lines;
  }

  /* ---------------- map ---------------- */

  generateMap(act) {
    const shape = [[2], [1, 3], [0, 2, 4], [1, 3], [0, 2, 4], [1, 3], [0, 2, 4], [2]];
    const nodes = [];
    shape.forEach((cols, row) => {
      cols.forEach((col) => {
        let type = "battle";
        if (row === 0) type = "start";
        else if (row === 7) type = "boss";
        else type = this.rollNodeType(act, row);
        nodes.push({ id: `r${row}c${col}`, row, col, type, done: false });
      });
    });
    for (const required of ["shop", "event", "special"]) {
      if (!nodes.some((n) => n.type === required)) {
        const candidates = nodes.filter((n) => n.row >= 2 && n.row <= 6 && n.type !== "boss");
        if (candidates.length) pick(candidates).type = required;
      }
    }
    const map = { act, nodes };
    nodes.forEach((node) => {
      if (node.row === 7) {
        node.conn = [];
      } else if (node.row === 6) {
        node.conn = nodes.filter((n) => n.row === 7).map((n) => n.id);
      } else {
        node.conn = nodes
          .filter((n) => n.row === node.row + 1 && Math.abs(n.col - node.col) <= 1)
          .map((n) => n.id);
      }
    });
    return map;
  }

  rollNodeType(act, row) {
    if (row === 1) return "battle";
    const entries = [
      { value: "battle", weight: 34 },
      { value: "event", weight: 16 },
      { value: "shop", weight: 11 },
      { value: "special", weight: 10 },
      { value: "elite", weight: act === 3 ? 14 : 10 },
      { value: "rest", weight: 10 },
      { value: "treasure", weight: 7 },
    ];
    return weightedPick(entries);
  }

  getNode(id) {
    return this.run?.map.nodes.find((n) => n.id === id) || null;
  }

  availableFrom(node, map = this.run?.map) {
    if (!node || !map) return [];
    if (node.row >= 7) return [];
    if (node.row === 6) return map.nodes.filter((n) => n.row === 7);
    return map.nodes.filter((n) => n.row === node.row + 1 && Math.abs(n.col - node.col) <= 1);
  }

  enterNode(nodeId) {
    if (!this.run) return;
    if (!this.run.available.includes(nodeId)) return;
    const node = this.getNode(nodeId);
    if (!node || node.done) return;
    if (["battle", "elite", "boss"].includes(node.type)) {
      this.startBattle(node);
      return;
    }
    if (node.type === "shop") {
      this.openShop(node);
      return;
    }
    if (node.type === "event") {
      this.openEvent(node);
      return;
    }
    if (node.type === "special") {
      this.openSpecial(node);
      return;
    }
    if (node.type === "rest") {
      this.openRest(node);
      return;
    }
    if (node.type === "treasure") {
      this.openTreasure(node);
    }
  }

  endRun(kind) {
    if (!this.run || this.run.ended) return;
    this.run.ended = true;
    const run = this.run;
    const wasClear = kind === "clear";
    const ash = wasClear
      ? Math.floor(100 + run.roomsCleared * 2 + run.gold * 0.05 + this.meta.prestige * 15)
      : Math.max(12, Math.floor(10 + run.roomsCleared * 4 + (run.act - 1) * 16 + run.battlesWon * 3 + run.gold * 0.08));

    this.meta.ash += ash;
    this.meta.totalAsh += ash;
    this.meta.runs += 1;
    this.meta.bestAct = Math.max(this.meta.bestAct, run.act);
    if (wasClear) {
      this.meta.clears += 1;
      this.meta.bossKills += 1;
    }
    this.saveMeta();
    this.combat = null;
    this.pending = {
      runSummary: {
        kind,
        ash,
        char: run.char,
        act: run.act,
        rooms: run.roomsCleared,
        gold: run.gold,
        deckSize: run.deck.length,
        charms: run.charms.length,
      },
    };
    this.screen = wasClear ? "runclear" : "gameover";
    this.emit();
  }

  returnFromRun() {
    this.run = null;
    this.combat = null;
    this.pending = null;
    this.setScreen("title");
  }

  prestigeLabel() {
    return PRESTIGE_STYLES[this.meta.prestige - 1] || null;
  }
}

Object.assign(Game.prototype, worldMethods, combatMethods);

/* Map locations: shops, events, offerings, rest, treasure, and rewards. */

import { CARDS, RARITY } from "./data/cards.js";
import { CHARMS, ACTS } from "./data/enemies.js";
import { EVENTS, SPECIALS } from "./data/events.js";
import { pick, shuffle, rand } from "./util.js";

function cardPrice(rarity) {
  const base = { common: 46, uncommon: 70, rare: 105 }[rarity] || 45;
  return base + rand(9) - 4;
}

function rewardRarity(roll) {
  if (roll < 10) return "rare";
  if (roll < 40) return "uncommon";
  return "common";
}

export const worldMethods = {
  /* ---------------- shops ---------------- */

  openShop(node) {
    const shop = {
      node,
      cards: [],
      charm: null,
      healCost: 30,
      healUsed: false,
      upgradeCost: 55,
      removeCost: 45,
      mode: null,
    };
    const used = new Set();
    let guard = 0;
    while (shop.cards.length < 4 && guard < 80) {
      guard += 1;
      const rarity = rewardRarity(Math.random() * 100);
      const pool = Object.keys(CARDS).filter((key) => CARDS[key].char === this.run.char && CARDS[key].rarity === rarity && !used.has(key));
      if (!pool.length) continue;
      const key = pick(pool);
      used.add(key);
      shop.cards.push({ key, price: cardPrice(rarity), sold: false });
    }
    const charmKey = this.randomAvailableCharm();
    if (charmKey) shop.charm = { key: charmKey, price: 85 + rand(11), sold: false };
    this.pending = { shop };
    this.screen = "shop";
    this.emit();
  },

  buyShopCard(index) {
    const shop = this.pending?.shop;
    const item = shop?.cards[index];
    if (!item || item.sold) return;
    if (this.run.gold < item.price) {
      this.notice = { text: "Not enough gold.", tone: "bad" };
      this.emit();
      return;
    }
    this.run.gold -= item.price;
    item.sold = true;
    this.addCard(item.key);
    this.notice = { text: `${CARDS[item.key].name} added to your deck.`, tone: "good" };
    this.emit();
  },

  buyShopCharm() {
    const shop = this.pending?.shop;
    if (!shop?.charm || shop.charm.sold) return;
    if (this.run.gold < shop.charm.price) {
      this.notice = { text: "Not enough gold.", tone: "bad" };
      this.emit();
      return;
    }
    this.run.gold -= shop.charm.price;
    shop.charm.sold = true;
    this.awardCharm(shop.charm.key);
    this.notice = { text: `Charm acquired: ${CHARMS[shop.charm.key].name}.`, tone: "good" };
    this.emit();
  },

  shopHeal() {
    const shop = this.pending?.shop;
    if (!shop || shop.healUsed) return;
    if (this.run.gold < shop.healCost) {
      this.notice = { text: "Not enough gold.", tone: "bad" };
      this.emit();
      return;
    }
    this.run.gold -= shop.healCost;
    const healed = Math.min(this.run.maxHp - this.run.hp, Math.ceil(this.run.maxHp * 0.35));
    this.run.hp += healed;
    shop.healUsed = true;
    this.notice = { text: `Patched up ${healed} HP.`, tone: "good" };
    this.emit();
  },

  setShopMode(mode) {
    if (!this.pending?.shop) return;
    this.pending.shop.mode = this.pending.shop.mode === mode ? null : mode;
    this.emit();
  },

  shopUpgrade(uid) {
    const shop = this.pending?.shop;
    const card = this.run.deck.find((c) => c.uid === uid);
    if (!shop || !card || card.upgraded) return;
    if (this.run.gold < shop.upgradeCost) {
      this.notice = { text: "Not enough gold.", tone: "bad" };
      this.emit();
      return;
    }
    this.run.gold -= shop.upgradeCost;
    card.upgraded = true;
    shop.mode = null;
    this.notice = { text: `${CARDS[card.key].name} honed for the rest of the run.`, tone: "good" };
    this.emit();
  },

  shopRemove(uid) {
    const shop = this.pending?.shop;
    if (!shop || this.run.deck.length <= 5) {
      this.notice = { text: "The deck is too small to cut.", tone: "bad" };
      this.emit();
      return;
    }
    const card = this.run.deck.find((c) => c.uid === uid);
    if (!card) return;
    if (this.run.gold < shop.removeCost) {
      this.notice = { text: "Not enough gold.", tone: "bad" };
      this.emit();
      return;
    }
    this.run.gold -= shop.removeCost;
    this.removeCard(uid);
    shop.mode = null;
    this.notice = { text: `${CARDS[card.key].name} forgotten.`, tone: "good" };
    this.emit();
  },

  leaveShop() {
    const shop = this.pending?.shop;
    if (!shop) return;
    this.completeNodeAndAdvance(shop.node);
  },

  /* ---------------- events ---------------- */

  openEvent(node) {
    let pool = EVENTS.filter((ev) => !this.run.seenEvents.includes(ev.id));
    if (!pool.length) {
      this.run.seenEvents = [];
      pool = EVENTS;
    }
    const event = pick(pool);
    this.run.seenEvents.push(event.id);
    this.pending = { event: { node, event, result: null } };
    this.screen = "event";
    this.emit();
  },

  chooseEvent(index) {
    const pending = this.pending?.event;
    if (!pending || pending.result) return;
    const choice = pending.event.choices[index];
    if (!choice) return;
    const lines = this.applySpec(choice.effect);
    pending.result = { choice, lines };
    this.screen = "event_result";
    this.emit();
  },

  leaveEvent() {
    const pending = this.pending?.event;
    if (!pending) return;
    this.completeNodeAndAdvance(pending.node);
  },

  /* ---------------- offering stones ---------------- */

  openSpecial(node) {
    this.pending = { special: { node, result: null } };
    this.screen = "special";
    this.emit();
  },

  takeOffering(id) {
    const pending = this.pending?.special;
    if (!pending || pending.result) return;
    const offering = SPECIALS.offerings.find((o) => o.id === id);
    if (!offering || !offering.requires(this.run)) return;
    const lines = [];
    const payLines = this.applySpec(offering.pay);
    lines.push(...payLines);
    const gainLines = this.applySpec(offering.gain);
    lines.push(...gainLines);
    this.run.boons.push({ name: offering.name, offer: offering.offer, boon: offering.boon });
    pending.result = { offering, lines };
    this.screen = "special_result";
    this.emit();
  },

  leaveSpecial() {
    const pending = this.pending?.special;
    if (!pending) return;
    this.completeNodeAndAdvance(pending.node);
  },

  /* ---------------- rest ---------------- */

  openRest(node) {
    this.pending = { rest: { node, mode: null, done: false, lines: [] } };
    this.screen = "rest";
    this.emit();
  },

  restHeal() {
    const rest = this.pending?.rest;
    if (!rest || rest.done) return;
    const healed = Math.min(this.run.maxHp - this.run.hp, Math.ceil(this.run.maxHp * 0.35));
    this.run.hp += healed;
    rest.done = true;
    rest.lines = [`Slept badly. Woke up ${healed} HP healthier.`];
    this.emit();
  },

  restUpgradeMode() {
    const rest = this.pending?.rest;
    if (!rest || rest.done) return;
    rest.mode = rest.mode === "upgrade" ? null : "upgrade";
    this.emit();
  },

  restUpgrade(uid) {
    const rest = this.pending?.rest;
    if (!rest || rest.done) return;
    const card = this.run.deck.find((c) => c.uid === uid);
    if (!card || card.upgraded) return;
    card.upgraded = true;
    rest.done = true;
    rest.mode = null;
    rest.lines = [`Sharpened ${CARDS[card.key].name}. It will not dull again this run.`];
    this.emit();
  },

  leaveRest() {
    const rest = this.pending?.rest;
    if (!rest) return;
    this.completeNodeAndAdvance(rest.node);
  },

  /* ---------------- treasure ---------------- */

  openTreasure(node) {
    const charmKey = this.randomAvailableCharm();
    const gold = 20 + this.run.act * 6 + rand(10);
    const lines = [];
    if (charmKey) {
      this.awardCharm(charmKey);
      lines.push(`Charm: ${CHARMS[charmKey].name}.`);
    } else {
      this.run.gold += 40;
      lines.push("The chest is full of charms you already own. You take 40 gold instead.");
    }
    this.run.gold += gold;
    lines.push(`Gold: ${gold}.`);
    this.pending = { treasure: { node, charmKey, gold, lines } };
    this.screen = "treasure";
    this.emit();
  },

  leaveTreasure() {
    const pending = this.pending?.treasure;
    if (!pending) return;
    this.completeNodeAndAdvance(pending.node);
  },

  /* ---------------- rewards ---------------- */

  buildRewardCards(mode = "normal") {
    const cards = [];
    const used = new Set();
    let guard = 0;
    while (cards.length < 3 && guard < 60) {
      guard += 1;
      let rarity;
      if (mode === "boss") rarity = "rare";
      else if (mode === "elite") rarity = rewardRarity(Math.random() * 100 - 12);
      else rarity = rewardRarity(Math.random() * 100);
      const pool = Object.keys(CARDS).filter((key) => {
        const def = CARDS[key];
        return def.char === this.run.char && def.rarity === rarity && !used.has(key);
      });
      if (!pool.length) continue;
      const key = pick(pool);
      used.add(key);
      cards.push({ key, upgraded: false });
    }
    return cards;
  },

  handleVictory(node) {
    if (!this.run || !this.combat) return;
    const run = this.run;
    run.hp = Math.max(1, this.combat.player.hp);
    run.battlesWon += 1;
    const isElite = node.type === "elite";
    const isBoss = node.type === "boss";
    let gold = 14 + run.act * 5 + rand(9);
    if (isElite) gold += 24;
    if (isBoss) gold += 38;
    run.gold += gold;
    let charmInfo = null;
    if (isElite || isBoss) {
      const key = this.randomAvailableCharm();
      if (key) {
        this.awardCharm(key);
        charmInfo = { key, ...CHARMS[key] };
      } else {
        run.gold += 30;
      }
    }
    for (const key of run.charms) {
      const charm = CHARMS[key];
      if (charm?.afterBattle) charm.afterBattle({ run, game: this });
    }
    this.pending = {
      reward: {
        node,
        gold,
        cards: this.buildRewardCards(isBoss ? "boss" : isElite ? "elite" : "normal"),
        charm: charmInfo,
        elite: isElite,
        boss: isBoss,
        taken: false,
      },
    };
    this.screen = "reward";
    this.emit();
  },

  chooseReward(index) {
    const reward = this.pending?.reward;
    if (!reward || reward.taken) return;
    const choice = reward.cards[index];
    if (!choice) return;
    reward.taken = true;
    this.addCard(choice.key);
    this.notice = { text: `${CARDS[choice.key].name} added to your deck.`, tone: "good" };
    this.completeNodeAndAdvance(reward.node);
  },

  skipReward() {
    const reward = this.pending?.reward;
    if (!reward || reward.taken) return;
    reward.taken = true;
    this.notice = { text: "You leave the card where it lies.", tone: "" };
    this.completeNodeAndAdvance(reward.node);
  },

  continueReward() {
    const reward = this.pending?.reward;
    if (!reward) return;
    this.completeNodeAndAdvance(reward.node);
  },

  completeNodeAndAdvance(node) {
    if (!node) return;
    node.done = true;
    const run = this.run;
    run.currentRow = node.row;
    run.currentNode = node.id;
    run.roomsCleared += 1;

    if (node.type === "boss") {
      this.combat = null;
      if (run.act < 3) {
        run.act += 1;
        const healed = Math.min(run.maxHp - run.hp, Math.ceil(run.maxHp * 0.25));
        run.hp += healed;
        run.map = this.generateMap(run.act);
        const start = run.map.nodes.find((n) => n.type === "start");
        run.currentNode = start.id;
        run.currentRow = 0;
        run.available = this.availableFrom(start, run.map).map((n) => n.id);
        this.pending = { actIntro: { act: run.act, healed } };
        this.screen = "act_intro";
        this.emit();
      } else {
        this.endRun("clear");
      }
      return;
    }

    run.available = this.availableFrom(node, run.map).map((n) => n.id);
    this.pending = null;
    this.combat = null;
    this.screen = "map";
    this.emit();
  },

  continueActIntro() {
    this.pending = null;
    this.screen = "map";
    this.emit();
  },

  /* ---------------- small helpers for UI ---------------- */

  currentAct() {
    return ACTS[this.run?.act || 1];
  },

  cardName(key) {
    return CARDS[key]?.name || key;
  },

  rarityOf(key) {
    return RARITY[CARDS[key]?.rarity] || RARITY.common;
  },
};

/* Combat: stamina, cards, intents, summons, statuses, and the turn loop. */

import { CHARACTERS } from "./data/characters.js";
import { CARDS, getEffects } from "./data/cards.js";
import {
  ENEMIES, NORMAL_ENCOUNTERS, ELITE_ENCOUNTERS, BOSS_ENCOUNTERS,
  CHARMS, ACTS, STATUS_INFO,
} from "./data/enemies.js";
import { pick, shuffle, clamp, rand } from "./util.js";

const TACO_BASE_HP = 12;
const TACO_BASE_ATTACK = 3;

function emptyStatuses() {
  return { bleed: 0, book: 0, weak: 0, vulnerable: 0 };
}

export const combatMethods = {
  startBattle(node) {
    let keys = [];
    if (node.type === "boss") keys = BOSS_ENCOUNTERS[this.run.act];
    else if (node.type === "elite") keys = pick(ELITE_ENCOUNTERS[this.run.act]);
    else keys = pick(NORMAL_ENCOUNTERS[this.run.act]);
    this.beginCombat(node, keys);
  },

  beginCombat(node, keys) {
    const run = this.run;
    const def = CHARACTERS[run.char];
    const player = {
      hp: run.hp,
      maxHp: run.maxHp,
      block: 0,
      overshield: run.char === "elizabeth" ? 5 : 0,
      strength: run.strength,
      crit: clamp(run.crit, 0, 0.9),
      critDamage: run.critDamage,
      weak: 0,
      vulnerable: 0,
      bleed: 0,
    };
    const combat = {
      node,
      type: node.type,
      player,
      enemies: [],
      drawPile: shuffle(run.deck.map((card) => ({ ...card }))),
      hand: [],
      discardPile: [],
      exhaustPile: [],
      stamina: 0,
      maxStamina: run.staminaMax,
      drawCount: run.drawCount,
      turn: 1,
      phase: "player",
      ended: false,
      pendingCard: null,
      log: [],
      firstTurnDraw: 0,
      firstTurnStamina: 0,
      critBonus: 0,
      thorns: 0,
      taco: null,
      startedAt: Date.now(),
    };
    if (run.char === "brittany") {
      const maxHp = TACO_BASE_HP + run.tacoMax;
      combat.taco = {
        name: "Taco",
        alive: true,
        hp: maxHp,
        maxHp,
        block: 0,
        attack: TACO_BASE_ATTACK + run.tacoAttack,
      };
    }
    this.combat = combat;
    combat.enemies = keys.map((key) => this.createEnemy(key));
    for (const charmKey of run.charms) {
      const charm = CHARMS[charmKey];
      if (charm?.combatStart) charm.combatStart({ combat, run, game: this });
    }
    this.log(`${ACTS[run.act].name} · ${node.type === "boss" ? "The boss is waiting." : "The board shifts."}`, "system");
    this.log(combat.enemies.map((e) => e.name).join("  ·  "), "muted");
    if (combat.taco) {
      this.log(`Taco is here. ${combat.taco.hp} HP. He will take the hits.`, "good");
    }
    if (run.char === "elizabeth") {
      this.log("Gilded Guard: Overshield persists between turns.", "good");
    }
    combat.stamina = combat.maxStamina + combat.firstTurnStamina;
    this.drawCards(combat.drawCount + combat.firstTurnDraw);
    this.log(`Turn 1 — spend ${combat.stamina} Stamina.`, "turn");
    this.screen = "combat";
    this.emit();
  },

  createEnemy(key) {
    const def = ENEMIES[key];
    return {
      key,
      uid: `e${this.uid++}`,
      name: def.name,
      hp: def.hp,
      maxHp: def.hp,
      block: def.block || 0,
      strength: 0,
      statuses: emptyStatuses(),
      taunt: false,
      enraged: false,
      alive: true,
      moveIndex: 0,
      pattern: [...def.pattern],
      moves: def.moves,
      tags: def.tags,
      crest: def.crest,
      color: def.color,
      flavor: def.flavor,
      boss: !!def.boss,
      minion: !!def.minion,
    };
  },

  log(text, tone = "") {
    if (!this.combat) return;
    this.combat.log.push({ text, tone, turn: this.combat.turn });
    if (this.combat.log.length > 90) this.combat.log.shift();
  },

  aliveEnemies() {
    return this.combat?.enemies.filter((e) => e.alive) || [];
  },

  tauntingEnemies() {
    return this.aliveEnemies().filter((e) => e.taunt);
  },

  drawCards(amount) {
    const combat = this.combat;
    if (!combat) return;
    for (let i = 0; i < amount; i += 1) {
      if (!combat.drawPile.length) {
        if (!combat.discardPile.length) break;
        combat.drawPile = shuffle(combat.discardPile);
        combat.discardPile = [];
      }
      const card = combat.drawPile.pop();
      if (card) combat.hand.push(card);
    }
  },

  selectCard(uid) {
    const combat = this.combat;
    if (!combat || combat.ended || combat.phase !== "player") return;
    if (combat.pendingCard === uid) {
      combat.pendingCard = null;
      this.emit();
      return;
    }
    const card = combat.hand.find((c) => c.uid === uid);
    if (!card) return;
    const def = CARDS[card.key];
    const cost = def.cost;
    if (combat.stamina < cost) {
      this.log("Not enough Stamina.", "bad");
      this.emit();
      return;
    }
    if (def.target === "enemy") {
      const taunts = this.tauntingEnemies();
      if (taunts.length) {
        this.playCard(uid, taunts[0].uid);
        return;
      }
      const alive = this.aliveEnemies();
      if (alive.length === 1) {
        this.playCard(uid, alive[0].uid);
        return;
      }
      combat.pendingCard = uid;
      this.emit();
      return;
    }
    this.playCard(uid);
  },

  cancelPending() {
    if (!this.combat) return;
    this.combat.pendingCard = null;
    this.emit();
  },

  playSelected(enemyUid) {
    const combat = this.combat;
    if (!combat?.pendingCard) return;
    const enemy = combat.enemies.find((e) => e.uid === enemyUid && e.alive);
    if (!enemy) return;
    const taunts = this.tauntingEnemies();
    if (taunts.length && !enemy.taunt) {
      this.log("The taunt holds your attention. Strike the one who demands it.", "bad");
      this.emit();
      return;
    }
    this.playCard(combat.pendingCard, enemyUid);
  },

  playCard(uid, targetUid) {
    const combat = this.combat;
    if (!combat || combat.ended || combat.phase !== "player") return;
    const index = combat.hand.findIndex((c) => c.uid === uid);
    if (index < 0) return;
    const card = combat.hand[index];
    const def = CARDS[card.key];
    if (combat.stamina < def.cost) {
      this.log("Not enough Stamina.", "bad");
      this.emit();
      return;
    }
    let target = null;
    if (def.target === "enemy") {
      const alive = this.aliveEnemies();
      if (!alive.length) return;
      target = combat.enemies.find((e) => e.uid === targetUid && e.alive) || alive[0];
    }

    combat.stamina -= def.cost;
    combat.hand.splice(index, 1);
    combat.pendingCard = null;
    this.log(`▸ ${def.name}${card.upgraded ? " +" : ""}`, "card");

    const effects = getEffects(card);
    for (const effect of effects) {
      this.resolveCardEffect(card, def, effect, target);
      if (!this.aliveEnemies().length) break;
      if (combat.player.hp <= 0) break;
    }

    if (def.exhaust) combat.exhaustPile.push(card);
    else combat.discardPile.push(card);

    if (!this.aliveEnemies().length) {
      this.finishVictory();
      return;
    }
    if (combat.player.hp <= 0) {
      this.playerDefeated();
      return;
    }
    this.emit();
  },

  resolveCardEffect(card, def, effect, target) {
    const combat = this.combat;
    const player = combat.player;
    const allTargets = def.target === "all";

    switch (effect.kind) {
      case "damage": {
        const targets = allTargets ? this.aliveEnemies() : target ? [target] : [];
        for (const enemy of targets) {
          if (!enemy.alive) continue;
          this.strikeEnemy(enemy, effect.amount, effect.hits || 1, { crit: true });
        }
        break;
      }
      case "damageIfBleed": {
        if (target?.alive && target.statuses.bleed > 0) {
          this.strikeEnemy(target, effect.amount, 1, { crit: true });
          this.log(`Bleeding target: +${effect.amount} bonus damage.`, "muted");
        }
        break;
      }
      case "block":
        player.block += effect.amount;
        this.log(`Gain ${effect.amount} Block.`, "good");
        break;
      case "overshield":
        player.overshield += effect.amount;
        this.log(`Gain ${effect.amount} Overshield.`, "good");
        break;
      case "status": {
        if (effect.target === "self") {
          if (effect.status === "crit") {
            combat.critBonus += effect.amount / 100;
            this.log(`+${effect.amount}% Crit this turn.`, "good");
          }
          break;
        }
        const targets = effect.target === "allEnemies" || allTargets ? this.aliveEnemies() : target ? [target] : [];
        for (const enemy of targets) {
          this.applyEnemyStatus(enemy, effect.status, effect.amount);
        }
        break;
      }
      case "multiplyStatus": {
        if (!target?.alive) break;
        if (effect.status === "book") {
          const stacks = target.statuses.book;
          if (stacks > 0) this.addBook(target, stacks);
        } else if (effect.status === "bleed") {
          target.statuses.bleed *= 2;
          this.log(`Bleed on ${target.name} doubles to ${target.statuses.bleed}.`, "good");
        }
        break;
      }
      case "draw":
        this.drawCards(effect.amount);
        this.log(`Draw ${effect.amount}.`, "muted");
        break;
      case "energy":
        combat.stamina += effect.amount;
        this.log(`Gain ${effect.amount} Stamina.`, "good");
        break;
      case "heal":
        player.hp = Math.min(player.maxHp, player.hp + effect.amount);
        this.log(`Heal ${effect.amount} HP.`, "good");
        break;
      case "loseHp":
        player.hp = Math.max(0, player.hp - effect.amount);
        this.log(`Lose ${effect.amount} HP.`, "bad");
        break;
      case "strength":
        player.strength += effect.amount;
        this.log(`Gain ${effect.amount} Strength.`, "good");
        break;
      case "summonMaxHp": {
        const taco = combat.taco;
        if (!taco) break;
        taco.maxHp += effect.amount;
        if (taco.alive) taco.hp += effect.amount;
        this.log(`Taco grows tougher. ${taco.hp}/${taco.maxHp} HP.`, "good");
        break;
      }
      case "summonHeal": {
        const taco = combat.taco;
        if (!taco || !taco.alive) {
          this.log("Taco is not here to heal.", "muted");
          break;
        }
        const before = taco.hp;
        taco.hp = Math.min(taco.maxHp, taco.hp + effect.amount);
        this.log(`Taco heals ${taco.hp - before} HP. ${taco.hp}/${taco.maxHp}.`, "good");
        break;
      }
      case "tacoBlock": {
        const taco = combat.taco;
        if (!taco || !taco.alive) break;
        taco.block += effect.amount;
        this.log(`Taco gains ${effect.amount} Block.`, "good");
        break;
      }
      case "tacoAttack": {
        const taco = combat.taco;
        if (!taco || !taco.alive) {
          this.log("Taco is not here. The card does nothing.", "muted");
          break;
        }
        if (target?.alive) this.tacoBite(target, effect.amount + taco.attack);
        break;
      }
      case "reviveTaco": {
        const taco = combat.taco;
        if (!taco) break;
        if (!taco.alive) {
          taco.alive = true;
          taco.hp = Math.min(taco.maxHp, effect.amount);
          taco.block = 0;
          this.log(`Taco returns! ${taco.hp}/${taco.maxHp} HP.`, "good");
        } else {
          const before = taco.hp;
          taco.hp = Math.min(taco.maxHp, taco.hp + effect.heal);
          this.log(`Taco heals ${taco.hp - before} HP.`, "good");
        }
        break;
      }
      default:
        break;
    }
  },

  strikeEnemy(enemy, amount, hits = 1, { crit = false, ignoreBlock = false, useStrength = true, label = null } = {}) {
    if (!enemy?.alive) return 0;
    const combat = this.combat;
    const player = combat.player;
    let total = 0;
    let critCount = 0;
    for (let i = 0; i < hits; i += 1) {
      if (!enemy.alive) break;
      let damage = amount + (useStrength ? player.strength : 0);
      let didCrit = false;
      if (crit) {
        const critChance = clamp(player.crit + combat.critBonus, 0, 0.95);
        if (Math.random() < critChance) {
          damage *= player.critDamage;
          didCrit = true;
          critCount += 1;
          if (this.run.char === "roxy") {
            combat.critBonus += 0.08;
            this.log("Hot Streak: +8% Crit this turn.", "good");
          }
        }
      }
      if (enemy.statuses.vulnerable > 0) damage *= 1.5;
      if (player.weak > 0) damage *= 0.75;
      damage = Math.max(1, Math.round(damage));
      if (ignoreBlock) {
        enemy.hp -= damage;
        total += damage;
      } else {
        const absorbed = Math.min(enemy.block, damage);
        enemy.block -= absorbed;
        const through = damage - absorbed;
        enemy.hp -= through;
        total += through;
      }
      if (enemy.hp <= 0) {
        enemy.hp = 0;
        enemy.alive = false;
      }
    }
    const critText = critCount ? ` · ${critCount} CRIT` : "";
    this.log(`${label || CHARACTERS[this.run.char].name} hits ${enemy.name} for ${total}${hits > 1 ? ` (${hits} hits${critText})` : critText}.`, critCount ? "good" : "damage");
    this.afterEnemyDamaged(enemy);
    return total;
  },

  tacoBite(enemy, amount) {
    if (!enemy?.alive) return;
    const combat = this.combat;
    const taco = combat.taco;
    if (!taco?.alive) return;
    const damage = Math.max(1, amount);
    const absorbed = Math.min(enemy.block, damage);
    enemy.block -= absorbed;
    const through = damage - absorbed;
    enemy.hp -= through;
    if (enemy.hp <= 0) {
      enemy.hp = 0;
      enemy.alive = false;
    }
    this.log(`Taco bites ${enemy.name} for ${through}.`, "good");
    this.afterEnemyDamaged(enemy);
  },

  afterEnemyDamaged(enemy) {
    if (!enemy) return;
    if (enemy.hp <= 0 && enemy.alive) {
      enemy.hp = 0;
      enemy.alive = false;
    }
    if (!enemy.alive) {
      if (!enemy.defeatLogged) {
        enemy.defeatLogged = true;
        this.log(`${enemy.name} is defeated.`, "good");
      }
      return;
    }
    if (enemy.boss && !enemy.enraged && enemy.hp <= enemy.maxHp * 0.5) {
      enemy.enraged = true;
      enemy.strength += 3;
      enemy.block += 10;
      this.log(`${enemy.name} stops pretending. Second phase.`, "boss");
    }
  },

  addBook(enemy, amount, silent = false) {
    if (!enemy?.alive || amount <= 0) return;
    enemy.statuses.book += amount;
    if (!silent) this.log(`${enemy.name} gains ${amount} Book (${enemy.statuses.book}/10).`, "book");
    let guard = 0;
    while (enemy.statuses.book >= 10 && enemy.alive && guard < 20) {
      guard += 1;
      enemy.statuses.book -= 10;
      const damage = Math.ceil(enemy.maxHp * 0.15);
      enemy.hp -= damage;
      this.log(`OVERDUE! ${enemy.name} takes ${damage} damage — 15% max HP.`, "book");
      this.afterEnemyDamaged(enemy);
    }
  },

  applyEnemyStatus(enemy, status, amount) {
    if (!enemy?.alive) return;
    if (status === "book") {
      this.addBook(enemy, amount);
      return;
    }
    if (status in enemy.statuses) {
      enemy.statuses[status] += amount;
      this.log(`${enemy.name} gains ${amount} ${STATUS_INFO[status]?.name || status}.`, status === "bleed" ? "bleed" : "muted");
    }
  },

  applyPlayerStatus(status, amount) {
    const player = this.combat.player;
    if (status in player) {
      player[status] += amount;
      this.log(`You gain ${amount} ${STATUS_INFO[status]?.name || status}.`, "bad");
    }
  },

  finishVictory() {
    const combat = this.combat;
    if (!combat || combat.ended) return;
    combat.ended = true;
    combat.phase = "victory";
    this.log("The board clears.", "system");
    this.handleVictory(combat.node);
  },

  playerDefeated() {
    const combat = this.combat;
    if (!combat || combat.ended) return;
    combat.ended = true;
    combat.phase = "defeat";
    combat.player.hp = 0;
    this.run.hp = 0;
    this.log("The checkmate is yours to wear.", "bad");
    this.endRun("dead");
  },

  endTurn() {
    const combat = this.combat;
    if (!combat || combat.ended || combat.phase !== "player") return;
    this.combat.hand.forEach((card) => this.combat.discardPile.push(card));
    this.combat.hand = [];
    this.combat.pendingCard = null;
    this.combat.critBonus = 0;
    combat.player.weak = Math.max(0, combat.player.weak - 1);
    combat.player.vulnerable = Math.max(0, combat.player.vulnerable - 1);
    this.log("You end your turn.", "turn");
    combat.phase = "enemy";
    this.runEnemyTurn();
  },

  runEnemyTurn() {
    const combat = this.combat;
    const actors = [...combat.enemies];
    for (const enemy of actors) {
      if (combat.ended) return;
      if (!enemy.alive) continue;
      enemy.block = 0;
      if (enemy.statuses.bleed > 0) {
        const bleed = enemy.statuses.bleed;
        enemy.hp -= bleed;
        this.log(`${enemy.name} bleeds for ${bleed}.`, "bleed");
        enemy.statuses.bleed = Math.max(0, enemy.statuses.bleed - 1);
        this.afterEnemyDamaged(enemy);
        if (!enemy.alive) continue;
      }
      const move = enemy.moves[enemy.pattern[enemy.moveIndex % enemy.pattern.length]];
      this.log(`${enemy.name}: ${move.name}.`, "enemy");
      this.executeEnemyMove(enemy, move);
      enemy.moveIndex += 1;
      enemy.statuses.weak = Math.max(0, enemy.statuses.weak - 1);
      enemy.statuses.vulnerable = Math.max(0, enemy.statuses.vulnerable - 1);
      if (combat.player.hp <= 0) {
        this.playerDefeated();
        return;
      }
      if (!this.aliveEnemies().length) {
        this.finishVictory();
        return;
      }
    }
    if (!this.aliveEnemies().length) {
      this.finishVictory();
      return;
    }
    if (combat.player.hp <= 0) {
      this.playerDefeated();
      return;
    }
    this.startPlayerTurn();
  },

  executeEnemyMove(enemy, move) {
    const combat = this.combat;
    if (move.block) {
      enemy.block += move.block;
      this.log(`${enemy.name} gains ${move.block} Block.`, "muted");
    }
    if (move.taunt) {
      enemy.taunt = true;
      this.log(`${enemy.name} taunts. Strike them or waste the turn.`, "bad");
    }
    if (move.strength) {
      enemy.strength += move.strength;
      this.log(`${enemy.name} gains ${move.strength} Strength.`, "bad");
    }
    if (move.strengthAll) {
      for (const ally of this.aliveEnemies()) ally.strength += move.strengthAll;
      this.log(`All enemies gain ${move.strengthAll} Strength.`, "bad");
    }
    if (move.heal) {
      enemy.hp = Math.min(enemy.maxHp, enemy.hp + move.heal);
      this.log(`${enemy.name} heals ${move.heal}.`, "bad");
    }
    if (move.healAll) {
      for (const ally of this.aliveEnemies()) ally.hp = Math.min(ally.maxHp, ally.hp + move.healAll);
      this.log(`All enemies heal ${move.healAll}.`, "bad");
    }
    if (move.summon) {
      if (combat.enemies.length >= 5) {
        enemy.block += 8;
        this.log("The room is too full. The summon becomes 8 Block.", "muted");
      } else {
        const summoned = this.createEnemy(move.summon);
        summoned.summoned = true;
        combat.enemies.push(summoned);
        this.log(`${enemy.name} summons ${summoned.name}.`, "bad");
      }
    }
    if (move.status) this.applyPlayerStatus(move.status.type, move.status.amount);
    if (move.status2) this.applyPlayerStatus(move.status2.type, move.status2.amount);

    if (move.dmg) {
      const hits = move.hits || 1;
      let totalToPlayer = 0;
      let totalToTaco = 0;
      let blocked = 0;
      for (let i = 0; i < hits; i += 1) {
        let raw = move.dmg + enemy.strength;
        if (enemy.statuses.weak > 0) raw *= 0.75;
        raw = Math.round(raw);
        if (move.aoe) {
          if (combat.taco?.alive) {
            const result = this.damageTaco(raw);
            totalToTaco += result.through;
            blocked += result.blocked;
          }
          if (combat.player.hp > 0) {
            const result = this.damagePlayer(raw);
            totalToPlayer += result.through;
            blocked += result.blocked;
          }
        } else if (combat.taco?.alive) {
          const result = this.damageTaco(raw);
          totalToTaco += result.through;
          blocked += result.blocked;
        } else {
          const result = this.damagePlayer(raw);
          totalToPlayer += result.through;
          blocked += result.blocked;
        }
        if (combat.player.hp <= 0) break;
      }
      const pieces = [];
      if (totalToTaco) pieces.push(`${totalToTaco} to Taco`);
      if (totalToPlayer) pieces.push(`${totalToPlayer} to you`);
      if (blocked) pieces.push(`${blocked} blocked`);
      if (!pieces.length) pieces.push("no damage through");
      this.log(`${move.name}: ${pieces.join(", ")}.`, totalToPlayer || totalToTaco ? "damage-in" : "muted");
      if (!combat.taco?.alive && combat.taco) {
        this.log("Taco is down. You are on your own.", "bad");
      }
    }
    if (move.dmg && combat.thorns > 0 && (!combat.taco || !combat.taco.alive || move.aoe)) {
      enemy.hp -= combat.thorns;
      this.log(`Thorn Pin pricks ${enemy.name} for ${combat.thorns}.`, "good");
      this.afterEnemyDamaged(enemy);
    }
  },

  damagePlayer(raw) {
    const player = this.combat.player;
    let damage = raw;
    if (player.vulnerable > 0) damage = Math.round(damage * 1.5);
    const blocked = Math.min(player.block, damage);
    player.block -= blocked;
    let remaining = damage - blocked;
    const shielded = Math.min(player.overshield, remaining);
    player.overshield -= shielded;
    remaining -= shielded;
    player.hp = Math.max(0, player.hp - remaining);
    return { blocked, through: remaining };
  },

  damageTaco(raw) {
    const taco = this.combat.taco;
    let damage = raw;
    const blocked = Math.min(taco.block, damage);
    taco.block -= blocked;
    let remaining = damage - blocked;
    taco.hp = Math.max(0, taco.hp - remaining);
    if (taco.hp <= 0) {
      taco.alive = false;
      taco.hp = 0;
    }
    return { blocked, through: remaining };
  },

  startPlayerTurn() {
    const combat = this.combat;
    if (combat.ended) return;
    combat.turn += 1;
    combat.phase = "player";
    combat.player.block = 0;
    combat.player.critBonus = 0;
    combat.critBonus = 0;
    if (combat.taco) combat.taco.block = 0;

    if (combat.player.bleed > 0) {
      const bleed = combat.player.bleed;
      combat.player.hp = Math.max(0, combat.player.hp - bleed);
      combat.player.bleed = Math.max(0, combat.player.bleed - 1);
      this.log(`You bleed for ${bleed}.`, "bleed");
      if (combat.player.hp <= 0) {
        this.playerDefeated();
        return;
      }
    }

    if (combat.taco?.alive) {
      const targets = this.aliveEnemies();
      if (targets.length) {
        const victim = pick(targets);
        this.tacoBite(victim, combat.taco.attack);
        if (!this.aliveEnemies().length) {
          this.finishVictory();
          return;
        }
      }
    }

    combat.stamina = combat.maxStamina;
    this.drawCards(combat.drawCount);
    this.log(`Turn ${combat.turn} — ${combat.stamina} Stamina. Ten seconds. Go.`, "turn");
    this.emit();
  },

  statusLine() {
    if (!this.combat) return "";
    const parts = [];
    const p = this.combat.player;
    if (p.strength) parts.push(`${p.strength} STR`);
    if (this.combat.critBonus) parts.push(`+${Math.round(this.combat.critBonus * 100)}% CRIT`);
    if (p.weak) parts.push(`${p.weak} WEAK`);
    if (p.vulnerable) parts.push(`${p.vulnerable} VULN`);
    if (p.bleed) parts.push(`${p.bleed} BLEED`);
    return parts.join(" · ");
  },

  enemyIntent(enemy) {
    if (!enemy?.alive) return null;
    return enemy.moves[enemy.pattern[enemy.moveIndex % enemy.pattern.length]];
  },

  canPlayCard(card) {
    if (!this.combat || this.combat.phase !== "player") return false;
    return this.combat.stamina >= CARDS[card.key].cost;
  },
};

/* ============================================================
   THE CHECKERBOARD — base, title, lobby, archive, wardrobe
   ============================================================ */

:root {
  --ink: #0b090b;
  --ink-2: #100d10;
  --panel: #141115;
  --panel-2: #191519;
  --panel-3: #201a1f;
  --cream: #efe6d2;
  --cream-2: #d9ceb7;
  --muted: #958c7d;
  --muted-2: #6e675e;
  --line: rgba(239, 230, 210, 0.14);
  --line-strong: rgba(239, 230, 210, 0.28);
  --red: #e96545;
  --red-deep: #7e2f22;
  --gold: #d8b16c;
  --green: #9cb98b;
  --pink: #f0a1b2;
  --blue: #b7c5df;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.55);
  --serif: "Cormorant Garamond", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --sans: "Space Grotesk", "Inter", system-ui, -apple-system, sans-serif;
  --mono: "IBM Plex Mono", "SFMono-Regular", Consolas, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  background: var(--ink);
  color-scheme: dark;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100dvh;
  color: var(--cream);
  background:
    radial-gradient(circle at 14% -8%, rgba(233, 101, 69, 0.11), transparent 34%),
    radial-gradient(circle at 92% 12%, rgba(183, 197, 223, 0.06), transparent 28%),
    radial-gradient(circle at 60% 110%, rgba(216, 177, 108, 0.06), transparent 35%),
    var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    linear-gradient(90deg, transparent 49.8%, rgba(239, 230, 210, 0.018) 50%, transparent 50.2%),
    linear-gradient(0deg, transparent 49.8%, rgba(239, 230, 210, 0.012) 50%, transparent 50.2%);
  background-size: 120px 120px;
  mask-image: radial-gradient(circle at center, black, transparent 82%);
}

.grain {
  position: fixed;
  inset: 0;
  z-index: 80;
  pointer-events: none;
  opacity: 0.035;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.86' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}

#app {
  position: relative;
  z-index: 1;
  min-height: 100dvh;
}

::selection {
  background: var(--red);
  color: var(--ink);
}

img {
  display: block;
  max-width: 100%;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  border: 0;
  background: none;
  cursor: pointer;
}

a {
  color: inherit;
}

h1,
h2,
h3,
h4,
p {
  margin: 0;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.22);
}

::-webkit-scrollbar-thumb {
  background: rgba(239, 230, 210, 0.18);
  border-radius: 99px;
}

/* ---------- shared type & utilities ---------- */

.mono,
.eyebrow,
.kicker,
.detail-label,
.stat-label,
.node-type,
.pill,
.tag,
.card-type,
.card-foot,
.cost,
.stamina-label,
.turn-label {
  font-family: var(--mono);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.24em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  content: "";
  width: 18px;
  height: 1px;
  background: currentColor;
  opacity: 0.7;
}

.eyebrow.no-line::before {
  display: none;
}

.muted {
  color: var(--muted);
}

.danger {
  color: var(--red);
}

.gold {
  color: var(--gold);
}

.green {
  color: var(--green);
}

.pink {
  color: var(--pink);
}

.blue {
  color: var(--blue);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.rule {
  width: 100%;
  height: 1px;
  border: 0;
  background: var(--line);
}

/* ---------- buttons ---------- */

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 44px;
  padding: 11px 20px;
  border: 1px solid var(--line-strong);
  color: var(--cream);
  background: rgba(239, 230, 210, 0.03);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.16em;
  line-height: 1.2;
  text-transform: uppercase;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 10px 100%, 0 calc(100% - 10px));
  transition: background 160ms ease, color 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.btn::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 1px solid transparent;
  pointer-events: none;
}

.btn:hover {
  border-color: var(--cream);
  background: rgba(239, 230, 210, 0.09);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn-primary {
  border-color: var(--cream);
  color: var(--ink);
  background: var(--cream);
}

.btn-primary:hover {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--ink);
}

.btn-accent {
  border-color: var(--red);
  background: var(--red);
  color: #fff8ee;
}

.btn-accent:hover {
  background: #f07a58;
  border-color: #f07a58;
}

.btn-ghost {
  border-color: var(--line);
  color: var(--cream-2);
  background: transparent;
}

.btn-small {
  min-height: 34px;
  padding: 7px 12px;
  font-size: 9px;
  letter-spacing: 0.12em;
}

.btn-wide {
  width: 100%;
}

.btn-danger {
  border-color: rgba(233, 101, 69, 0.5);
  color: #ffd3c9;
  background: rgba(233, 101, 69, 0.08);
}

.btn:disabled,
.btn[disabled] {
  cursor: not-allowed;
  opacity: 0.36;
  transform: none;
}

.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: color 150ms ease;
}

.back-link:hover {
  color: var(--cream);
}

.back-link::before {
  content: "←";
  font-size: 14px;
}

/* ---------- title ---------- */

.title-screen {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
  padding: max(22px, env(safe-area-inset-top)) clamp(20px, 4vw, 58px) 24px;
  overflow: hidden;
}

.title-screen::before {
  content: "";
  position: absolute;
  top: 13%;
  left: 50%;
  width: min(62vw, 900px);
  aspect-ratio: 1;
  border: 1px solid rgba(239, 230, 210, 0.05);
  transform: translateX(-50%) rotate(45deg);
  pointer-events: none;
}

.title-screen::after {
  content: "";
  position: absolute;
  top: 18%;
  left: 50%;
  width: min(45vw, 680px);
  aspect-ratio: 1;
  border: 1px solid rgba(239, 230, 210, 0.035);
  transform: translateX(-50%) rotate(45deg);
  pointer-events: none;
}

.title-header {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
  animation: fade-in 700ms ease both;
}

.brand-line {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.brand-mark {
  display: grid;
  width: 30px;
  height: 30px;
  border: 1px solid var(--line-strong);
  place-items: center;
  font-family: var(--serif);
  font-size: 15px;
  letter-spacing: 0;
  color: var(--cream);
}

.title-meta {
  display: flex;
  align-items: center;
  gap: 18px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.title-meta strong {
  color: var(--cream);
  font-weight: 500;
}

.title-hero {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(440px, 0.98fr);
  flex: 1;
  gap: clamp(24px, 3vw, 52px);
  align-items: center;
  padding: clamp(34px, 5vh, 76px) 0 clamp(24px, 4vh, 54px);
}

.title-copy {
  max-width: 680px;
  animation: rise-in 800ms 80ms ease both;
}

.title-kicker {
  margin-bottom: clamp(16px, 2.5vh, 28px);
}

.game-title {
  display: flex;
  flex-direction: column;
  margin-left: -0.05em;
  font-family: var(--serif);
  font-size: clamp(4.6rem, 10.3vw, 10.5rem);
  font-weight: 500;
  letter-spacing: -0.045em;
  line-height: 0.73;
  text-transform: uppercase;
}

.game-title span {
  padding-left: 0.08em;
  color: var(--muted-2);
  font-size: 0.35em;
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0.16em;
  line-height: 1.4;
}

.game-title em {
  color: var(--cream);
  font-style: normal;
  text-shadow: 0 0 80px rgba(239, 230, 210, 0.08);
}

.title-lede {
  max-width: 520px;
  margin-top: clamp(22px, 3.5vh, 38px);
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: clamp(1.15rem, 1.7vw, 1.5rem);
  font-style: italic;
  line-height: 1.32;
}

.title-lede strong {
  color: var(--cream);
  font-style: normal;
  font-weight: 500;
}

.title-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 11px;
  margin-top: clamp(24px, 4vh, 38px);
}

.title-actions .btn {
  min-width: 159px;
  min-height: 48px;
}

.title-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 9px 18px;
  margin-top: 22px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.title-badges span {
  display: inline-flex;
  gap: 7px;
  align-items: center;
}

.title-badges span::before {
  content: "·";
  color: var(--red);
}

.title-art {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 440px;
  padding: 20px 0 30px;
  animation: rise-in 900ms 160ms ease both;
}

.title-art::before {
  content: "";
  position: absolute;
  bottom: 10px;
  width: 86%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--line-strong), transparent);
}

.title-art::after {
  content: "FOUR GIRLS · ONE STAIRCASE";
  position: absolute;
  right: 2%;
  bottom: -4px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  writing-mode: vertical-rl;
}

.title-card {
  position: relative;
  display: flex;
  flex-direction: column;
  width: clamp(128px, 13vw, 190px);
  aspect-ratio: 3 / 4.15;
  margin-left: clamp(-44px, -3.2vw, -24px);
  padding: 0;
  border: 1px solid var(--line);
  color: var(--cream);
  background: var(--panel);
  transform: rotate(var(--rot));
  transform-origin: 50% 100%;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
  transition: transform 280ms cubic-bezier(0.2, 0.7, 0.2, 1), border-color 200ms ease, filter 200ms ease;
  overflow: hidden;
}

.title-card:first-child {
  margin-left: 0;
}

.title-card:hover,
.title-card:focus-visible {
  z-index: 5;
  border-color: var(--char, var(--cream));
  filter: brightness(1.08);
  transform: translateY(-16px) rotate(0deg) scale(1.03);
}

.title-card-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 24%;
  filter: saturate(0.64) contrast(1.06) brightness(0.76);
  transition: filter 220ms ease, transform 700ms ease;
}

.title-card:hover .title-card-img {
  filter: saturate(0.95) contrast(1.03) brightness(0.9);
  transform: scale(1.035);
}

.title-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(11, 9, 11, 0.04) 35%, rgba(11, 9, 11, 0.94) 100%);
}

.title-card-top {
  position: absolute;
  z-index: 2;
  top: 10px;
  left: 11px;
  color: rgba(239, 230, 210, 0.65);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
}

.title-card-info {
  position: absolute;
  z-index: 2;
  right: 11px;
  bottom: 12px;
  left: 11px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.title-card-info strong {
  font-family: var(--serif);
  font-size: clamp(1.15rem, 1.7vw, 1.55rem);
  font-weight: 600;
  line-height: 1;
}

.title-card-info span {
  color: var(--char);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.title-card-info em {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7px;
  font-style: normal;
  letter-spacing: 0.07em;
  line-height: 1.4;
}

.title-footer {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
  padding-top: 15px;
  border-top: 1px solid var(--line);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  line-height: 1.6;
  text-transform: uppercase;
}

.title-footer a,
.title-footer button {
  color: var(--muted);
  text-decoration: underline;
  text-underline-offset: 3px;
  font-family: inherit;
  font-size: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
}

.title-footer a:hover,
.title-footer button:hover {
  color: var(--cream);
}

/* ---------- page shell ---------- */

.page-shell {
  min-height: 100dvh;
  padding: max(24px, env(safe-area-inset-top)) clamp(18px, 4vw, 56px) 40px;
}

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 19px;
  border-bottom: 1px solid var(--line);
}

.page-header-meta {
  display: flex;
  gap: 18px;
  align-items: center;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.page-header-meta strong {
  color: var(--cream);
  font-weight: 500;
}

.page-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  padding: clamp(36px, 6vh, 68px) 0 clamp(24px, 4vh, 38px);
}

.page-heading h1 {
  margin-top: 8px;
  font-size: clamp(2.7rem, 5vw, 5rem);
  font-weight: 500;
  letter-spacing: -0.035em;
  line-height: 0.9;
}

.page-heading h1 em {
  color: var(--muted);
  font-style: italic;
  font-weight: 400;
}

.page-heading p {
  max-width: 390px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.15rem;
  font-style: italic;
  line-height: 1.35;
}

/* ---------- character select ---------- */

.select-screen {
  max-width: 1480px;
  margin: 0 auto;
}

.char-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(12px, 1.8vw, 22px);
}

.char-tile {
  position: relative;
  display: block;
  width: 100%;
  min-height: 430px;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--panel);
  text-align: left;
  transition: transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;
  animation: rise-in 650ms ease both;
  animation-delay: var(--delay, 0ms);
}

.char-tile:hover,
.char-tile:focus-visible {
  z-index: 2;
  border-color: var(--char);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.42);
  transform: translateY(-7px);
}

.char-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(11, 9, 11, 0.05) 27%, rgba(11, 9, 11, 0.92) 73%, var(--ink) 100%);
}

.char-tile-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 20%;
  filter: saturate(0.7) brightness(0.78) contrast(1.04);
  transition: transform 700ms ease, filter 220ms ease;
}

.char-tile:hover .char-tile-img {
  filter: saturate(1) brightness(0.88) contrast(1.02);
  transform: scale(1.035);
}

.char-tile-top {
  position: absolute;
  z-index: 2;
  top: 16px;
  right: 16px;
  left: 16px;
  display: flex;
  justify-content: space-between;
  color: rgba(239, 230, 210, 0.62);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.char-tile-top span:last-child {
  color: var(--char);
}

.char-tile-content {
  position: absolute;
  z-index: 2;
  right: 17px;
  bottom: 17px;
  left: 17px;
}

.char-tile-name {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--serif);
  font-size: clamp(1.9rem, 2.5vw, 2.75rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 0.95;
}

.char-tile-name em {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  font-style: normal;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.char-tile-epithet {
  margin-top: 5px;
  color: var(--char);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.char-tile-style {
  margin-top: 14px;
  padding-top: 11px;
  border-top: 1px solid rgba(239, 230, 210, 0.16);
  color: var(--cream-2);
  font-size: 12px;
  line-height: 1.4;
}

.char-tile-style span {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.char-tile-lock {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.char-tile-lock::before {
  content: "✦";
}

.select-hint {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-top: 20px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* ---------- briefing ---------- */

.briefing-screen {
  max-width: 1280px;
  margin: 0 auto;
}

.briefing-grid {
  display: grid;
  grid-template-columns: minmax(300px, 0.82fr) minmax(0, 1.18fr);
  gap: clamp(28px, 5vw, 76px);
  align-items: center;
  padding: clamp(24px, 4vh, 52px) 0;
}

.briefing-art {
  position: relative;
  min-height: 610px;
  border: 1px solid var(--line);
  background: var(--panel);
  overflow: hidden;
}

.briefing-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 48%, rgba(11, 9, 11, 0.9) 100%);
}

.briefing-portrait {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 18%;
  filter: saturate(0.83) contrast(1.03);
}

.briefing-art-info {
  position: absolute;
  z-index: 2;
  right: 24px;
  bottom: 22px;
  left: 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 16px;
}

.briefing-art-info strong {
  font-family: var(--serif);
  font-size: clamp(2.4rem, 4vw, 4.1rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.8;
}

.briefing-art-info span {
  color: var(--char);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.briefing-copy {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.briefing-title h1 {
  margin-top: 7px;
  font-size: clamp(3rem, 5vw, 5.4rem);
  font-weight: 500;
  letter-spacing: -0.05em;
  line-height: 0.82;
}

.briefing-title h1 em {
  color: var(--muted);
  font-style: italic;
  font-weight: 400;
}

.briefing-bio {
  max-width: 590px;
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: 1.27rem;
  font-style: italic;
  line-height: 1.36;
}

.briefing-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.briefing-stat {
  padding: 12px 12px 12px 0;
}

.briefing-stat + .briefing-stat {
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.briefing-stat span {
  display: block;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.briefing-stat strong {
  display: block;
  margin-top: 4px;
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 500;
  line-height: 1;
}

.briefing-stat small {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
}

.passive-box {
  padding: 15px 17px;
  border-left: 2px solid var(--char);
  background: rgba(239, 230, 210, 0.035);
}

.passive-box h3 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.passive-box h3 span {
  color: var(--char);
  font-family: var(--serif);
  font-size: 1.1rem;
  letter-spacing: 0;
  text-transform: none;
}

.passive-box p {
  margin-top: 5px;
  color: var(--cream-2);
  font-size: 12.5px;
  line-height: 1.5;
}

.outfit-select {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.outfit-select-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.outfit-options {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
}

.outfit-chip {
  min-height: 54px;
  padding: 8px 9px;
  border: 1px solid var(--line);
  color: var(--muted);
  background: var(--panel);
  text-align: left;
  transition: border-color 150ms ease, background 150ms ease, color 150ms ease;
}

.outfit-chip strong {
  display: block;
  overflow: hidden;
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0.06em;
  line-height: 1.35;
  text-overflow: ellipsis;
  text-transform: uppercase;
}

.outfit-chip span {
  display: block;
  margin-top: 4px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.outfit-chip:hover {
  border-color: var(--line-strong);
}

.outfit-chip.active {
  border-color: var(--char);
  background: rgba(239, 230, 210, 0.07);
  color: var(--cream);
}

.outfit-chip.locked {
  opacity: 0.38;
}

.outfit-chip.locked strong {
  color: var(--muted);
}

.starter-deck-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 7px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.starter-deck {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.starter-card {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 7px;
  border: 1px solid var(--line);
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
}

.starter-card b {
  display: grid;
  width: 14px;
  height: 14px;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  place-items: center;
  color: var(--gold);
  font-size: 7px;
  font-weight: 500;
}

.briefing-meta-buffs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.meta-buff {
  padding: 4px 7px;
  border: 1px solid rgba(216, 177, 108, 0.24);
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.06em;
}

/* ---------- archive ---------- */

.archive-screen {
  max-width: 1100px;
  margin: 0 auto;
}

.archive-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 28px;
  padding: 20px 22px;
  border: 1px solid var(--line);
  background: linear-gradient(120deg, rgba(216, 177, 108, 0.055), transparent 60%);
}

.ash-display {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.ash-display strong {
  color: var(--cream);
  font-family: var(--serif);
  font-size: 2.9rem;
  font-weight: 500;
  line-height: 0.8;
}

.ash-display span {
  color: var(--gold);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.archive-stats {
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
}

.archive-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.archive-stat span {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.archive-stat strong {
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 500;
}

.upgrade-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.upgrade-card {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  gap: 13px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--line);
  background: var(--panel);
  transition: border-color 150ms ease, background 150ms ease;
}

.upgrade-card:hover {
  border-color: var(--line-strong);
  background: var(--panel-2);
}

.upgrade-sigil {
  display: grid;
  width: 36px;
  height: 36px;
  border: 1px solid var(--line-strong);
  place-items: center;
  color: var(--gold);
  font-family: var(--serif);
  font-size: 1.35rem;
}

.upgrade-copy h3 {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.upgrade-copy p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.upgrade-ranks {
  display: flex;
  gap: 4px;
  margin-top: 7px;
}

.rank-pip {
  width: 17px;
  height: 3px;
  background: rgba(239, 230, 210, 0.12);
}

.rank-pip.on {
  background: var(--char, var(--gold));
}

.upgrade-buy {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.upgrade-buy span {
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.prestige-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 24px;
  align-items: center;
  margin-top: 28px;
  padding: 20px 22px;
  border: 1px solid rgba(216, 177, 108, 0.27);
  background:
    linear-gradient(120deg, rgba(216, 177, 108, 0.08), transparent 60%),
    var(--panel);
}

.prestige-panel h2 {
  font-size: 2rem;
  font-weight: 500;
  line-height: 1;
}

.prestige-panel p {
  max-width: 600px;
  margin-top: 7px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.55;
}

.prestige-pips {
  display: flex;
  gap: 5px;
  margin-top: 10px;
}

.prestige-pip {
  width: 28px;
  height: 4px;
  background: rgba(239, 230, 210, 0.13);
}

.prestige-pip.on {
  background: var(--gold);
}

/* ---------- wardrobe ---------- */

.wardrobe-screen {
  max-width: 1240px;
  margin: 0 auto;
}

.wardrobe-group {
  padding: 24px 0;
  border-top: 1px solid var(--line);
}

.wardrobe-group-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 13px;
}

.wardrobe-group-head h2 {
  font-size: 1.9rem;
  font-weight: 500;
  line-height: 1;
}

.wardrobe-group-head h2 span {
  margin-right: 8px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
}

.wardrobe-group-head p {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.outfit-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 9px;
}

.outfit-card {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--panel);
  text-align: left;
  transition: border-color 150ms ease, transform 150ms ease;
}

.outfit-card:hover {
  border-color: var(--char);
  transform: translateY(-2px);
}

.outfit-card-img {
  width: 100%;
  aspect-ratio: 3 / 3.55;
  object-fit: cover;
  object-position: 50% 18%;
  filter: saturate(0.72) brightness(0.84);
}

.outfit-card-info {
  padding: 9px 10px 11px;
  border-top: 1px solid var(--line);
}

.outfit-card-info strong {
  display: block;
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0.06em;
  line-height: 1.35;
  text-transform: uppercase;
}

.outfit-card-info span {
  display: block;
  margin-top: 3px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.outfit-card.locked .outfit-card-img {
  filter: grayscale(1) brightness(0.2) blur(2px);
}

.outfit-card.locked::after {
  content: "LOCKED · PRESTIGE " attr(data-tier);
  position: absolute;
  top: 50%;
  left: 50%;
  padding: 5px 9px;
  border: 1px solid var(--line-strong);
  color: var(--muted);
  background: rgba(11, 9, 11, 0.85);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-align: center;
  transform: translate(-50%, -50%);
  white-space: nowrap;
}

.outfit-card.equipped {
  border-color: var(--gold);
}

.outfit-card.equipped::before {
  content: "WEARING";
  position: absolute;
  z-index: 2;
  top: 7px;
  right: 7px;
  padding: 3px 6px;
  color: var(--ink);
  background: var(--gold);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
}

/* ---------- tips ---------- */

.tips-screen {
  max-width: 1000px;
  margin: 0 auto;
}

.tips-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 28px 0 50px;
}

.tip-card {
  padding: 20px;
  border: 1px solid var(--line);
  background: var(--panel);
}

.tip-card:nth-child(3n + 1) {
  border-color: rgba(233, 101, 69, 0.25);
}

.tip-number {
  color: var(--red);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
}

.tip-card h2 {
  margin-top: 9px;
  font-size: 1.65rem;
  font-weight: 500;
  line-height: 1;
}

.tip-card p {
  margin-top: 9px;
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.6;
}

/* ---------- generic portraits / fallback ---------- */

.portrait {
  background:
    linear-gradient(135deg, rgba(239, 230, 210, 0.12), transparent 55%),
    radial-gradient(circle at 50% 25%, var(--char, #6b5347), #141115 70%);
}

.portrait.missing {
  opacity: 0;
}

/* ---------- modal ---------- */

.modal-scrim {
  position: fixed;
  z-index: 90;
  inset: 0;
  display: grid;
  padding: 22px;
  background: rgba(5, 4, 5, 0.82);
  backdrop-filter: blur(8px);
  place-items: center;
  animation: fade-in 160ms ease both;
}

.modal {
  width: min(560px, 100%);
  max-height: min(82dvh, 820px);
  overflow: auto;
  border: 1px solid var(--line-strong);
  background: var(--panel);
  box-shadow: var(--shadow);
  animation: rise-in 220ms ease both;
}

.modal-wide {
  width: min(980px, 100%);
}

.modal-head {
  position: sticky;
  z-index: 2;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 15px 18px;
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}

.modal-head h2 {
  font-size: 1.45rem;
  font-weight: 500;
  line-height: 1;
}

.modal-close {
  display: grid;
  width: 32px;
  height: 32px;
  border: 1px solid var(--line);
  color: var(--muted);
  place-items: center;
}

.modal-close:hover {
  border-color: var(--cream);
  color: var(--cream);
}

.modal-body {
  padding: 18px;
}

.modal-copy {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.6;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 18px;
}

/* ---------- animations ---------- */

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse-soft {
  0%, 100% { box-shadow: 0 0 0 0 rgba(239, 230, 210, 0.16); }
  50% { box-shadow: 0 0 0 7px rgba(239, 230, 210, 0); }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

/* ---------- responsive: lobby ---------- */

@media (max-width: 1120px) {
  .title-hero {
    grid-template-columns: minmax(0, 0.95fr) minmax(380px, 1.05fr);
  }

  .char-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .char-tile {
    min-height: 390px;
  }

  .briefing-grid {
    grid-template-columns: minmax(280px, 0.8fr) minmax(0, 1.2fr);
  }
}

@media (max-width: 900px) {
  .title-screen {
    padding-right: 22px;
    padding-left: 22px;
  }

  .title-hero {
    grid-template-columns: 1fr;
    gap: 12px;
    padding-top: 42px;
  }

  .title-art {
    min-height: 310px;
    padding-top: 20px;
  }

  .title-card {
    width: clamp(112px, 23vw, 180px);
    margin-left: -22px;
  }

  .title-copy {
    max-width: 720px;
  }

  .game-title {
    font-size: clamp(4rem, 15vw, 8rem);
  }

  .title-footer {
    flex-direction: column;
    align-items: flex-start;
  }

  .briefing-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .briefing-art {
    min-height: 460px;
    max-height: 56vh;
  }

  .outfit-options {
    grid-template-columns: repeat(2, 1fr);
  }

  .outfit-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  body {
    font-size: 14px;
  }

  .title-screen {
    padding: max(16px, env(safe-area-inset-top)) 15px 18px;
  }

  .title-header {
    gap: 10px;
  }

  .brand-line {
    font-size: 8px;
    letter-spacing: 0.15em;
  }

  .title-meta {
    gap: 9px;
    font-size: 8px;
  }

  .title-meta span:nth-child(2) {
    display: none;
  }

  .game-title {
    font-size: clamp(3.6rem, 20vw, 5.5rem);
    line-height: 0.75;
  }

  .game-title span {
    font-size: 0.31em;
  }

  .title-lede {
    margin-top: 22px;
    font-size: 1.14rem;
  }

  .title-actions {
    gap: 8px;
  }

  .title-actions .btn {
    flex: 1 1 46%;
    min-width: 0;
    padding-right: 12px;
    padding-left: 12px;
    font-size: 9px;
  }

  .title-art {
    min-height: 270px;
    padding-bottom: 8px;
  }

  .title-card {
    width: 27vw;
    max-width: 126px;
    margin-left: -19px;
  }

  .title-card-info strong {
    font-size: 1.05rem;
  }

  .title-card-info em {
    display: none;
  }

  .title-badges {
    margin-top: 16px;
    font-size: 7px;
  }

  .page-shell {
    padding: max(16px, env(safe-area-inset-top)) 14px 30px;
  }

  .page-header-meta {
    gap: 10px;
    font-size: 8px;
  }

  .page-heading {
    display: block;
    padding: 32px 0 22px;
  }

  .page-heading h1 {
    margin-top: 6px;
    font-size: 2.8rem;
  }

  .page-heading p {
    margin-top: 12px;
    font-size: 1rem;
  }

  .char-grid {
    gap: 9px;
  }

  .char-tile {
    min-height: 300px;
  }

  .char-tile-content {
    right: 11px;
    bottom: 11px;
    left: 11px;
  }

  .char-tile-name {
    font-size: 1.65rem;
  }

  .char-tile-style {
    margin-top: 9px;
    padding-top: 8px;
    font-size: 10px;
  }

  .char-tile-lock {
    font-size: 7px;
  }

  .select-hint {
    flex-direction: column;
    gap: 6px;
  }

  .briefing-title h1 {
    font-size: 3.4rem;
  }

  .briefing-art {
    min-height: 380px;
  }

  .briefing-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .briefing-stat:nth-child(3) {
    border-left: 0;
  }

  .briefing-stat:nth-child(n + 3) {
    border-top: 1px solid var(--line);
  }

  .archive-summary {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
    padding: 16px;
  }

  .upgrade-grid {
    grid-template-columns: 1fr;
  }

  .prestige-panel {
    grid-template-columns: 1fr;
  }

  .outfit-grid {
    gap: 7px;
  }

  .wardrobe-group-head {
    display: block;
  }

  .wardrobe-group-head p {
    margin-top: 4px;
  }

  .tips-grid {
    grid-template-columns: 1fr;
  }

  .modal-scrim {
    padding: 10px;
  }

  .modal {
    max-height: 88dvh;
  }
}

/* ============================================================
   THE CHECKERBOARD — run bar, map, combat, locations, endings
   ============================================================ */

/* ---------- run bar ---------- */

.run-bar {
  position: sticky;
  z-index: 30;
  top: 0;
  display: flex;
  align-items: center;
  gap: 18px;
  min-height: 66px;
  padding: 9px clamp(14px, 3vw, 42px);
  border-bottom: 1px solid var(--line);
  background: rgba(11, 9, 11, 0.9);
  backdrop-filter: blur(14px);
}

.run-brand {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.run-brand:hover {
  color: var(--cream);
}

.run-brand .brand-mark {
  width: 27px;
  height: 27px;
  font-size: 13px;
}

.run-identity {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding-left: 15px;
  border-left: 1px solid var(--line);
}

.run-identity-img {
  width: 38px;
  height: 46px;
  flex: 0 0 auto;
  border: 1px solid var(--line-strong);
  object-fit: cover;
  object-position: 50% 20%;
  filter: saturate(0.8);
}

.run-identity-copy {
  min-width: 0;
}

.run-identity-copy span {
  display: block;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.run-identity-copy strong {
  display: block;
  overflow: hidden;
  max-width: 170px;
  font-family: var(--serif);
  font-size: 1.2rem;
  font-weight: 500;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.run-vitals {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-left: auto;
}

.run-vital {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 52px;
}

.run-vital span {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.run-vital strong {
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.run-vital strong.hp {
  color: var(--red);
}

.run-vital strong.gold {
  color: var(--gold);
}

.run-hp-bar {
  display: flex;
  width: 132px;
  height: 4px;
  margin-top: 2px;
  background: rgba(239, 230, 210, 0.1);
  overflow: hidden;
}

.run-hp-bar i {
  display: block;
  height: 100%;
  background: var(--red);
  transition: width 280ms ease;
}

.run-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.run-action {
  display: grid;
  width: 34px;
  height: 34px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  place-items: center;
  transition: border-color 150ms ease, color 150ms ease;
}

.run-action:hover {
  border-color: var(--cream);
  color: var(--cream);
}

.run-action.active {
  border-color: var(--gold);
  color: var(--gold);
}

/* ---------- map ---------- */

.map-screen {
  min-height: 100dvh;
}

.map-page {
  display: grid;
  grid-template-columns: minmax(210px, 270px) minmax(0, 1fr) minmax(210px, 270px);
  gap: clamp(16px, 2.4vw, 34px);
  width: min(1420px, 100%);
  margin: 0 auto;
  padding: clamp(22px, 3.4vh, 38px) clamp(14px, 3vw, 36px) 50px;
  align-items: start;
}

.map-main {
  min-width: 0;
}

.map-heading {
  margin-bottom: 14px;
  text-align: center;
}

.map-heading h1 {
  margin-top: 4px;
  font-size: clamp(2.15rem, 3.4vw, 3.45rem);
  font-weight: 500;
  letter-spacing: -0.035em;
  line-height: 0.9;
}

.map-heading h1 em {
  color: var(--muted);
  font-style: italic;
  font-weight: 400;
}

.map-heading p {
  margin-top: 8px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 0.95rem;
  font-style: italic;
}

.map-board-wrap {
  display: flex;
  justify-content: center;
}

.map-board {
  position: relative;
  width: 100%;
  max-width: 468px;
  aspect-ratio: 5 / 8;
  border: 1px solid var(--line-strong);
  background:
    radial-gradient(circle at 50% 100%, rgba(233, 101, 69, 0.05), transparent 35%),
    #0d0b0e;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.38);
  overflow: hidden;
}

.map-board::before {
  content: "";
  position: absolute;
  z-index: 3;
  inset: 7px;
  border: 1px solid rgba(239, 230, 210, 0.055);
  pointer-events: none;
}

.map-grid {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  grid-template-rows: repeat(8, 1fr);
}

.map-tile {
  border-right: 1px solid rgba(239, 230, 210, 0.026);
  border-bottom: 1px solid rgba(239, 230, 210, 0.026);
}

.map-tile.dark {
  background: rgba(239, 230, 210, 0.036);
}

.map-tile.light {
  background: rgba(239, 230, 210, 0.008);
}

.map-lines {
  position: absolute;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.map-line {
  stroke: rgba(239, 230, 210, 0.11);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.map-line.active {
  stroke: var(--char, var(--gold));
  stroke-width: 1.4;
  opacity: 0.7;
}

.map-line.done {
  stroke: rgba(239, 230, 210, 0.19);
}

.map-node {
  position: absolute;
  z-index: 4;
  display: grid;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(239, 230, 210, 0.22);
  border-radius: 50%;
  color: var(--muted);
  background: #100d11;
  place-items: center;
  transform: translate(-50%, -50%);
  transition: border-color 150ms ease, color 150ms ease, background 150ms ease, box-shadow 150ms ease, transform 150ms ease;
}

.map-node .node-icon {
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1;
}

.map-node .node-label {
  position: absolute;
  top: calc(100% + 5px);
  left: 50%;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  white-space: nowrap;
  transform: translateX(-50%);
  opacity: 0;
  pointer-events: none;
  transition: opacity 150ms ease;
}

.map-node.available {
  cursor: pointer;
  border-color: var(--node-color, var(--cream));
  color: var(--node-color, var(--cream));
  background: #191419;
  box-shadow: 0 0 0 3px rgba(239, 230, 210, 0.04);
  animation: pulse-soft 2.6s ease-in-out infinite;
}

.map-node.available:hover {
  z-index: 8;
  background: var(--node-color, var(--cream));
  color: var(--ink);
  transform: translate(-50%, -50%) scale(1.16);
}

.map-node.available .node-label {
  opacity: 1;
}

.map-node.current {
  border-color: var(--cream);
  color: var(--cream);
  background: var(--cream);
  box-shadow: 0 0 0 4px rgba(239, 230, 210, 0.08);
}

.map-node.current .node-icon {
  color: var(--ink);
}

.map-node.current .node-label {
  opacity: 1;
  color: var(--cream);
}

.map-node.done:not(.current) {
  border-color: rgba(239, 230, 210, 0.1);
  color: var(--muted-2);
  background: rgba(16, 13, 17, 0.76);
}

.map-node.locked {
  opacity: 0.4;
  pointer-events: none;
}

.map-node.boss {
  width: 50px;
  height: 50px;
  border-color: rgba(233, 101, 69, 0.65);
  color: var(--red);
  background: #170d0d;
}

.map-node.boss .node-icon {
  font-size: 24px;
}

.map-node.boss.available {
  animation: boss-pulse 2.2s ease-in-out infinite;
}

.map-node.boss.current {
  color: var(--ink);
  background: var(--red);
}

.map-node.boss .node-label {
  top: auto;
  bottom: calc(100% + 6px);
  color: var(--red);
  font-size: 7px;
}

.map-node.start {
  width: 30px;
  height: 30px;
  border-color: rgba(239, 230, 210, 0.24);
  color: var(--muted);
  background: #0e0c0f;
}

.map-node.start.current {
  color: var(--cream);
  background: transparent;
}

.map-node.start .node-label {
  display: none;
}

.map-node[data-type="battle"] { --node-color: #d8cdb6; }
.map-node[data-type="elite"] { --node-color: #e96545; }
.map-node[data-type="shop"] { --node-color: #d8b16c; }
.map-node[data-type="event"] { --node-color: #9cb98b; }
.map-node[data-type="special"] { --node-color: #f0a1b2; }
.map-node[data-type="rest"] { --node-color: #b7c5df; }
.map-node[data-type="treasure"] { --node-color: #e8c982; }
.map-node[data-type="boss"] { --node-color: #e96545; }

@keyframes boss-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(233, 101, 69, 0.28); }
  50% { box-shadow: 0 0 0 10px rgba(233, 101, 69, 0); }
}

.board-caption {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  width: 100%;
  max-width: 468px;
  margin: 11px auto 0;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* map panels */

.map-aside {
  position: sticky;
  top: 88px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.panel {
  border: 1px solid var(--line);
  background: rgba(20, 17, 21, 0.86);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.panel-head strong {
  color: var(--cream-2);
  font-weight: 500;
}

.panel-body {
  padding: 12px;
}

.run-portrait-card {
  display: flex;
  gap: 11px;
  align-items: flex-end;
  min-height: 122px;
  padding: 12px;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, transparent, rgba(11, 9, 11, 0.92)),
    var(--panel);
  overflow: hidden;
}

.run-portrait-card img {
  width: 62px;
  height: 88px;
  flex: 0 0 auto;
  border: 1px solid var(--line-strong);
  object-fit: cover;
  object-position: 50% 20%;
}

.run-portrait-copy {
  min-width: 0;
}

.run-portrait-copy h2 {
  font-size: 1.7rem;
  font-weight: 500;
  line-height: 0.9;
}

.run-portrait-copy span {
  display: block;
  margin-top: 3px;
  color: var(--char);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.run-portrait-copy small {
  display: block;
  margin-top: 9px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7px;
  line-height: 1.4;
}

.stat-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 7px 0;
  border-bottom: 1px solid rgba(239, 230, 210, 0.07);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.stat-row:last-child {
  border-bottom: 0;
}

.stat-row strong {
  color: var(--cream-2);
  font-weight: 500;
}

.act-panel {
  position: relative;
  padding: 15px;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 100% 0%, rgba(239, 230, 210, 0.07), transparent 38%),
    var(--panel);
  overflow: hidden;
}

.act-panel::after {
  content: attr(data-roman);
  position: absolute;
  right: 10px;
  bottom: -24px;
  color: rgba(239, 230, 210, 0.045);
  font-family: var(--serif);
  font-size: 6rem;
  line-height: 1;
}

.act-panel h3 {
  margin-top: 5px;
  font-size: 1.5rem;
  font-weight: 500;
  line-height: 1;
}

.act-panel p {
  margin-top: 7px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 0.9rem;
  font-style: italic;
  line-height: 1.35;
}

.act-boss {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--red);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.act-boss::before {
  content: "♛";
  font-size: 13px;
}

.boon-list,
.charm-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.boon-item,
.charm-item {
  display: flex;
  gap: 7px;
  align-items: flex-start;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.boon-item::before {
  content: "✦";
  color: var(--gold);
  font-size: 9px;
  line-height: 1.35;
}

.charm-item::before {
  content: "◇";
  color: var(--green);
  font-size: 9px;
  line-height: 1.35;
}

.boon-item strong,
.charm-item strong {
  color: var(--cream-2);
  font-weight: 500;
}

.empty-note {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.5;
  letter-spacing: 0.04em;
}

.legend-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 10px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.legend-icon {
  display: grid;
  width: 18px;
  height: 18px;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--legend, var(--muted));
  font-family: var(--serif);
  font-size: 9px;
  place-items: center;
}

/* ---------- combat ---------- */

.combat-screen {
  display: flex;
  flex-direction: column;
  height: 100dvh;
  min-height: 660px;
  overflow: hidden;
}

.combat-bar {
  position: relative;
  z-index: 30;
  flex: 0 0 auto;
  min-height: 58px;
  padding-top: 7px;
  padding-bottom: 7px;
  background: rgba(11, 9, 11, 0.94);
}

.combat-bar .run-brand {
  display: none;
}

.combat-bar .run-identity {
  border-left: 0;
  padding-left: 0;
}

.combat-bar .run-hp-bar {
  width: 108px;
}

.combat-turn {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-right: auto;
  margin-left: 4px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.combat-turn strong {
  color: var(--cream);
  font-weight: 500;
}

.battlefield {
  display: grid;
  grid-template-columns: minmax(220px, 272px) minmax(0, 1fr) minmax(220px, 280px);
  flex: 1 1 auto;
  gap: clamp(14px, 2vw, 26px);
  width: min(1440px, 100%);
  min-height: 0;
  margin: 0 auto;
  padding: 18px clamp(14px, 2.8vw, 34px) 14px;
  overflow: auto;
}

.player-column {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.combat-player {
  position: relative;
  border: 1px solid var(--line);
  background: var(--panel);
  overflow: hidden;
}

.combat-player-art {
  position: relative;
  height: clamp(148px, 23vh, 210px);
  overflow: hidden;
}

.combat-player-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 20%;
  filter: saturate(0.82) contrast(1.03);
}

.combat-player-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 34%, rgba(20, 17, 21, 0.94) 100%);
}

.combat-player-name {
  position: absolute;
  z-index: 2;
  right: 12px;
  bottom: 9px;
  left: 12px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
}

.combat-player-name h2 {
  font-size: 1.85rem;
  font-weight: 500;
  line-height: 0.85;
}

.combat-player-name span {
  color: var(--char);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.combat-player-body {
  padding: 11px 12px 13px;
}

.hp-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.hp-line strong {
  color: var(--cream);
  font-size: 13px;
  font-weight: 500;
}

.hp-line strong em {
  color: var(--muted);
  font-style: normal;
  font-size: 9px;
}

.hp-bar {
  position: relative;
  height: 6px;
  margin-top: 5px;
  background: rgba(239, 230, 210, 0.09);
  overflow: hidden;
}

.hp-bar i {
  display: block;
  height: 100%;
  background: var(--red);
  transition: width 300ms ease;
}

.hp-bar.player i {
  background: linear-gradient(90deg, #b74235, var(--red));
}

.hp-bar.enemy i {
  background: linear-gradient(90deg, #883a32, #d86b5d);
}

.hp-bar.taco i {
  background: linear-gradient(90deg, #c78b66, #e4b17f);
}

.shield-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 7px;
}

.shield-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border: 1px solid rgba(183, 197, 223, 0.3);
  color: var(--blue);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
}

.shield-chip::before {
  content: "◇";
  font-size: 8px;
}

.stamina-block {
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
}

.stamina-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted-2);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.stamina-label strong {
  color: var(--gold);
  font-size: 10px;
  font-weight: 500;
}

.stamina-pips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.stamina-pip {
  width: 13px;
  height: 13px;
  border: 1px solid rgba(216, 177, 108, 0.35);
  border-radius: 50%;
  background: transparent;
}

.stamina-pip.on {
  border-color: var(--gold);
  background: var(--gold);
  box-shadow: 0 0 8px rgba(216, 177, 108, 0.28);
}

.player-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 8px;
  margin-top: 9px;
  padding-top: 8px;
  border-top: 1px solid var(--line);
}

.player-stat {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.player-stat strong {
  color: var(--cream-2);
  font-weight: 500;
}

.status-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 9px;
}

.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 5px;
  border: 1px solid color-mix(in srgb, var(--status-color, var(--muted)) 42%, transparent);
  color: var(--status-color, var(--muted));
  background: color-mix(in srgb, var(--status-color, var(--muted)) 7%, transparent);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  line-height: 1.2;
  text-transform: uppercase;
}

.status-chip::before {
  content: attr(data-sigil);
  font-size: 8px;
}

.passive-strip {
  padding: 9px 10px;
  border: 1px solid var(--line);
  background: rgba(239, 230, 210, 0.025);
}

.passive-strip strong {
  display: block;
  color: var(--char);
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.passive-strip p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.45;
}

.taco-card {
  padding: 10px;
  border: 1px dashed rgba(228, 177, 127, 0.38);
  background: rgba(228, 177, 127, 0.035);
}

.taco-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.taco-head strong {
  color: #e4b17f;
  font-family: var(--serif);
  font-size: 1.15rem;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
}

.taco-card .hp-bar {
  margin-top: 4px;
}

.taco-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 5px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.taco-card.down {
  opacity: 0.55;
}

/* enemy side */

.enemy-column {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.combat-location {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.combat-location span:last-child {
  color: var(--red);
}

.enemy-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  gap: 10px;
  align-content: start;
}

.enemy-card {
  position: relative;
  min-height: 210px;
  padding: 12px;
  border: 1px solid var(--line);
  background:
    radial-gradient(circle at 85% 0%, color-mix(in srgb, var(--enemy) 9%, transparent), transparent 42%),
    var(--panel);
  transition: border-color 150ms ease, transform 150ms ease, opacity 150ms ease;
  animation: rise-in 360ms ease both;
}

.enemy-card::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: var(--enemy);
  opacity: 0.45;
}

.enemy-card.boss {
  min-height: 245px;
  border-color: rgba(233, 101, 69, 0.37);
  background:
    radial-gradient(circle at 80% 0%, rgba(233, 101, 69, 0.1), transparent 45%),
    linear-gradient(150deg, rgba(233, 101, 69, 0.045), transparent 50%),
    var(--panel);
}

.enemy-card.dead {
  min-height: 88px;
  opacity: 0.28;
  filter: grayscale(0.8);
}

.enemy-card.targetable {
  cursor: crosshair;
  border-color: var(--gold);
  box-shadow: 0 0 0 2px rgba(216, 177, 108, 0.13);
  transform: translateY(-3px);
}

.enemy-card.targetable:hover {
  background:
    radial-gradient(circle at 85% 0%, rgba(216, 177, 108, 0.12), transparent 45%),
    var(--panel-2);
}

.enemy-card.taunting {
  border-color: rgba(233, 101, 69, 0.4);
}

.enemy-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.enemy-crest {
  display: grid;
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--enemy) 48%, transparent);
  border-radius: 50%;
  color: var(--enemy);
  font-family: var(--serif);
  font-size: 14px;
  place-items: center;
}

.enemy-title {
  min-width: 0;
  flex: 1;
}

.enemy-title h3 {
  font-family: var(--serif);
  font-size: clamp(1.05rem, 1.5vw, 1.35rem);
  font-weight: 500;
  line-height: 1;
}

.enemy-title p {
  margin-top: 3px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.07em;
  line-height: 1.4;
  text-transform: uppercase;
}

.intent-chip {
  min-width: 72px;
  padding: 5px 6px;
  border: 1px solid rgba(239, 230, 210, 0.2);
  background: #0e0c0f;
  text-align: right;
}

.intent-chip span {
  display: block;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.intent-chip strong {
  display: block;
  margin-top: 2px;
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0.02em;
  line-height: 1.4;
}

.intent-chip.hostile {
  border-color: rgba(233, 101, 69, 0.26);
}

.intent-chip.hostile strong {
  color: #f0a594;
}

.enemy-hp {
  margin-top: 12px;
}

.enemy-statuses {
  min-height: 24px;
  margin-top: 9px;
}

.enemy-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 9px;
}

.enemy-tag {
  padding: 2px 5px;
  border: 1px solid var(--line);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.enemy-flavor {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(239, 230, 210, 0.06);
  color: var(--muted-2);
  font-family: var(--serif);
  font-size: 0.78rem;
  font-style: italic;
  line-height: 1.32;
}

.boss-ribbon {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  margin-bottom: 5px;
  color: var(--red);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.boss-ribbon::before {
  content: "♛";
  font-size: 9px;
}

/* combat side log */

.combat-side {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--line);
  background: rgba(20, 17, 21, 0.72);
}

.combat-side-head {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 11px;
  border-bottom: 1px solid var(--line);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.combat-side-head strong {
  color: var(--cream-2);
  font-weight: 500;
}

.combat-log {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-height: 160px;
  padding: 8px 11px;
  overflow-y: auto;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.55;
}

.log-entry {
  padding: 3px 0;
  border-bottom: 1px solid rgba(239, 230, 210, 0.035);
  color: var(--muted);
}

.log-entry:last-child {
  border-bottom: 0;
}

.log-entry .log-turn {
  margin-right: 4px;
  color: var(--muted-2);
  font-size: 6px;
  opacity: 0.65;
}

.log-entry.turn {
  margin-top: 5px;
  color: var(--cream);
  font-weight: 500;
}

.log-entry.system {
  color: var(--gold);
}

.log-entry.card {
  color: var(--cream-2);
}

.log-entry.good {
  color: var(--green);
}

.log-entry.bad,
.log-entry.damage-in {
  color: var(--red);
}

.log-entry.damage {
  color: #e9a289;
}

.log-entry.bleed {
  color: #e08c8c;
}

.log-entry.book {
  color: var(--green);
}

.log-entry.enemy {
  color: #c9b4a1;
}

.log-entry.boss {
  color: var(--red);
  font-weight: 600;
  letter-spacing: 0.02em;
}

.log-entry.muted {
  color: var(--muted-2);
}

.side-summary {
  padding: 8px 11px;
  border-top: 1px solid var(--line);
}

.side-summary-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.side-summary-row + .side-summary-row {
  margin-top: 4px;
}

.side-summary-row strong {
  color: var(--cream-2);
  font-weight: 500;
}

/* hand */

.hand-zone {
  position: relative;
  z-index: 20;
  flex: 0 0 auto;
  padding: 0 clamp(12px, 2.8vw, 34px) max(12px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--line);
  background:
    linear-gradient(0deg, rgba(11, 9, 11, 0.98) 60%, rgba(11, 9, 11, 0.82)),
    var(--ink);
}

.hand-zone::before {
  content: "";
  position: absolute;
  top: -30px;
  right: 0;
  left: 0;
  height: 30px;
  background: linear-gradient(0deg, rgba(11, 9, 11, 0.78), transparent);
  pointer-events: none;
}

.hand-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: min(1380px, 100%);
  margin: 0 auto;
  padding: 7px 0;
}

.hand-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.hand-meta strong {
  color: var(--cream-2);
  font-weight: 500;
}

.target-prompt {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 8px;
  border: 1px solid rgba(216, 177, 108, 0.4);
  color: var(--gold);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.target-prompt button {
  color: var(--cream);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.hand-layout {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  width: min(1380px, 100%);
  margin: 0 auto;
}

.hand-scroll {
  display: flex;
  flex: 1;
  gap: 7px;
  min-width: 0;
  padding: 9px 2px 4px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
}

.hand-scroll::-webkit-scrollbar {
  height: 4px;
}

.end-turn-wrap {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 5px;
  width: 122px;
  flex: 0 0 auto;
  padding-bottom: 5px;
}

.end-turn {
  min-height: 54px;
  padding: 9px 12px;
  border: 1px solid var(--cream);
  color: var(--ink);
  background: var(--cream);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: background 160ms ease, border-color 160ms ease;
}

.end-turn:hover {
  border-color: var(--gold);
  background: var(--gold);
}

.end-turn small {
  display: block;
  margin-top: 2px;
  font-size: 6px;
  font-weight: 400;
  letter-spacing: 0.06em;
  opacity: 0.6;
}

.end-turn-meta {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.06em;
  text-align: center;
  text-transform: uppercase;
}

/* game cards */

.game-card {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 166px;
  min-width: 166px;
  min-height: 214px;
  padding: 26px 11px 10px;
  border: 1px solid var(--line-strong);
  border-top: 2px solid var(--rarity, var(--line-strong));
  color: var(--cream);
  background:
    radial-gradient(circle at 80% 5%, color-mix(in srgb, var(--char, #c7bca8) 10%, transparent), transparent 42%),
    linear-gradient(165deg, #1c171c, #120f13 65%);
  font-family: var(--sans);
  text-align: left;
  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
  overflow: hidden;
}

button.game-card {
  cursor: pointer;
}

.game-card::after {
  content: "";
  position: absolute;
  right: 8px;
  bottom: 20px;
  width: 42px;
  height: 42px;
  border: 1px solid color-mix(in srgb, var(--char, #c7bca8) 14%, transparent);
  rotate: 45deg;
  pointer-events: none;
}

.game-card:hover {
  border-color: var(--rarity, var(--cream));
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.35);
  transform: translateY(-7px);
}

.game-card.selected {
  border-color: var(--gold);
  box-shadow: 0 0 0 2px rgba(216, 177, 108, 0.23), 0 15px 35px rgba(0, 0, 0, 0.4);
  transform: translateY(-13px);
}

.game-card.unplayable {
  opacity: 0.42;
  transform: none;
}

.game-card.unplayable:hover {
  transform: none;
  box-shadow: none;
}

.game-card .cost {
  position: absolute;
  top: 7px;
  left: 8px;
  display: grid;
  width: 25px;
  height: 25px;
  border: 1px solid rgba(216, 177, 108, 0.5);
  border-radius: 50%;
  color: var(--gold);
  font-size: 10px;
  font-weight: 600;
  place-items: center;
}

.game-card .card-type {
  position: absolute;
  top: 9px;
  right: 9px;
  color: var(--muted-2);
  font-size: 6px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.card-glyph {
  position: absolute;
  top: 26px;
  right: 7px;
  color: color-mix(in srgb, var(--char, #c7bca8) 10%, transparent);
  font-family: var(--serif);
  font-size: 4rem;
  font-weight: 600;
  line-height: 0.8;
  pointer-events: none;
}

.game-card .card-name {
  position: relative;
  z-index: 1;
  margin-top: 7px;
  font-family: var(--serif);
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 0.95;
}

.game-card .card-name i {
  color: var(--gold);
  font-style: normal;
}

.game-card .card-divider {
  width: 28px;
  height: 1px;
  margin: 8px 0 7px;
  background: var(--rarity, var(--line-strong));
  opacity: 0.7;
}

.game-card .card-text {
  position: relative;
  z-index: 1;
  color: var(--cream-2);
  font-size: 10.5px;
  line-height: 1.45;
}

.game-card .card-foot {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 6px;
  margin-top: auto;
  padding-top: 10px;
  color: var(--muted-2);
  font-size: 6px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.game-card .card-foot span:last-child {
  color: var(--rarity, var(--muted-2));
}

.rarity-starter { --rarity: #817b70; }
.rarity-common { --rarity: #b9b19e; }
.rarity-uncommon { --rarity: #83b7a2; }
.rarity-rare { --rarity: #e4b86c; }

.card-mini {
  min-height: 0;
}

/* combat mobile log */

.log-toggle {
  display: none;
}

/* ---------- shared location screens ---------- */

.location-screen {
  min-height: 100dvh;
  padding-bottom: 50px;
}

.location-wrap {
  width: min(1080px, calc(100% - 32px));
  margin: 0 auto;
  padding: clamp(28px, 6vh, 64px) 0;
}

.location-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}

.location-head h1 {
  margin-top: 6px;
  font-size: clamp(2.8rem, 5vw, 5rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.86;
}

.location-head h1 em {
  color: var(--muted);
  font-style: italic;
  font-weight: 400;
}

.location-head p {
  max-width: 360px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.02rem;
  font-style: italic;
  line-height: 1.35;
}

.location-gold {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.location-gold strong {
  color: var(--gold);
  font-family: var(--serif);
  font-size: 2rem;
  font-weight: 500;
  letter-spacing: 0;
}

/* ---------- rewards ---------- */

.reward-screen {
  min-height: 100dvh;
  padding: max(30px, env(safe-area-inset-top)) 18px 50px;
}

.reward-wrap {
  width: min(1040px, 100%);
  margin: 0 auto;
}

.reward-head {
  padding: clamp(20px, 5vh, 54px) 0 24px;
  text-align: center;
}

.reward-head h1 {
  margin-top: 8px;
  font-size: clamp(3rem, 7vw, 6.4rem);
  font-weight: 500;
  letter-spacing: -0.055em;
  line-height: 0.8;
}

.reward-head h1 em {
  color: var(--gold);
  font-style: italic;
  font-weight: 400;
}

.reward-head p {
  margin-top: 13px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.12rem;
  font-style: italic;
}

.reward-summary {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 9px 22px;
  margin-top: 18px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.reward-summary strong {
  color: var(--cream-2);
  font-weight: 500;
}

.reward-cards {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  margin-top: 28px;
}

.reward-cards .game-card {
  width: 196px;
  min-height: 248px;
}

.reward-cards .card-text {
  font-size: 11.5px;
}

.reward-charm {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin: 22px auto 0;
  padding: 10px 16px;
  width: fit-content;
  border: 1px solid rgba(216, 177, 108, 0.3);
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.reward-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 28px;
}

/* ---------- shop ---------- */

.shop-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.38fr) minmax(255px, 0.62fr);
  gap: 24px;
  align-items: start;
}

.shop-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 10px;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.shop-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.shop-item {
  position: relative;
  display: block;
  width: 100%;
  padding: 0;
  border: 1px solid var(--line);
  background: var(--panel);
  text-align: left;
  transition: border-color 150ms ease, transform 150ms ease, opacity 150ms ease;
}

.shop-item:hover {
  border-color: var(--rarity, var(--cream));
  transform: translateY(-2px);
}

.shop-item.sold {
  opacity: 0.32;
  pointer-events: none;
}

.shop-item .game-card {
  width: 100%;
  min-width: 0;
  min-height: 205px;
  border: 0;
  border-top: 2px solid var(--rarity);
}

.shop-price {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border-top: 1px solid var(--line);
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.shop-price strong {
  color: var(--gold);
  font-weight: 500;
}

.shop-services {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.service-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 12px 13px;
  border: 1px solid var(--line);
  background: var(--panel);
  text-align: left;
  transition: border-color 150ms ease, background 150ms ease;
}

.service-card:hover {
  border-color: var(--line-strong);
  background: var(--panel-2);
}

.service-copy strong {
  display: block;
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.service-copy span {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.service-price {
  flex: 0 0 auto;
  color: var(--gold);
  font-family: var(--mono);
  font-size: 9px;
}

.service-card.active {
  border-color: var(--gold);
  background: rgba(216, 177, 108, 0.06);
}

.service-card:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.shop-charm {
  margin-top: 16px;
  padding: 13px;
  border: 1px solid rgba(156, 185, 139, 0.3);
  background: rgba(156, 185, 139, 0.035);
}

.shop-charm-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: baseline;
  color: var(--green);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.shop-charm-head strong {
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: 1.15rem;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
}

.shop-charm p {
  margin-top: 5px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.shop-charm .btn {
  margin-top: 9px;
}

.deck-picker {
  margin-top: 16px;
  padding: 14px;
  border: 1px solid rgba(216, 177, 108, 0.3);
  background: rgba(216, 177, 108, 0.03);
}

.deck-picker-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 10px;
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.deck-picker-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px;
  max-height: 310px;
  overflow-y: auto;
}

.deck-pick {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 9px;
  border: 1px solid var(--line);
  color: var(--muted);
  background: var(--panel);
  font-family: var(--mono);
  font-size: 8px;
  text-align: left;
}

.deck-pick:hover {
  border-color: var(--gold);
  color: var(--cream);
}

.deck-pick strong {
  color: var(--cream-2);
  font-weight: 500;
}

.deck-pick span {
  color: var(--gold);
  white-space: nowrap;
}

.deck-pick:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

/* ---------- events & offerings ---------- */

.event-screen,
.special-screen {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
}

.event-screen::before,
.special-screen::before {
  content: attr(data-glyph);
  position: absolute;
  top: 42%;
  left: 50%;
  color: rgba(239, 230, 210, 0.025);
  font-family: var(--serif);
  font-size: min(65vw, 720px);
  font-weight: 600;
  line-height: 0.55;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.event-stage,
.special-stage {
  position: relative;
  z-index: 1;
  width: min(840px, calc(100% - 32px));
  margin: 0 auto;
  padding: clamp(38px, 8vh, 86px) 0 60px;
}

.event-kicker {
  color: var(--red);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.event-title,
.special-title {
  margin-top: 10px;
  font-size: clamp(3rem, 7vw, 5.8rem);
  font-weight: 500;
  letter-spacing: -0.05em;
  line-height: 0.83;
}

.event-body {
  max-width: 660px;
  margin-top: 22px;
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: clamp(1.18rem, 1.7vw, 1.42rem);
  font-style: italic;
  line-height: 1.45;
}

.choice-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 30px;
}

.choice {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  gap: 13px;
  align-items: center;
  width: 100%;
  padding: 13px 15px;
  border: 1px solid var(--line);
  color: var(--cream);
  background: rgba(20, 17, 21, 0.7);
  text-align: left;
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.choice:hover {
  border-color: var(--tone-color, var(--cream));
  background: rgba(239, 230, 210, 0.05);
  transform: translateX(3px);
}

.choice.good { --tone-color: var(--green); }
.choice.pact { --tone-color: var(--red); }
.choice.quiet { --tone-color: var(--muted); }

.choice-mark {
  display: grid;
  width: 30px;
  height: 30px;
  border: 1px solid var(--tone-color, var(--line-strong));
  color: var(--tone-color, var(--cream));
  font-family: var(--serif);
  font-size: 16px;
  place-items: center;
}

.choice-copy strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 500;
  line-height: 1;
}

.choice-copy span {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.02em;
  line-height: 1.4;
}

.choice-tag {
  color: var(--tone-color, var(--muted));
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.result-box {
  margin-top: 26px;
  padding: 19px;
  border: 1px solid var(--line);
  background: rgba(20, 17, 21, 0.8);
}

.result-box h2 {
  color: var(--gold);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.result-lines {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-top: 12px;
}

.result-line {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  color: var(--cream-2);
  font-size: 12px;
  line-height: 1.45;
}

.result-line::before {
  content: "·";
  color: var(--gold);
}

.special-stage {
  width: min(980px, calc(100% - 32px));
}

.special-lede {
  max-width: 660px;
  margin-top: 14px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.18rem;
  font-style: italic;
  line-height: 1.45;
}

.offerings {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 30px;
}

.offering {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-height: 200px;
  padding: 17px;
  border: 1px solid var(--line);
  color: var(--cream);
  background: rgba(20, 17, 21, 0.74);
  text-align: left;
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.offering:hover:not(:disabled) {
  border-color: var(--pink);
  background: rgba(240, 161, 178, 0.035);
  transform: translateY(-3px);
}

.offering:disabled {
  opacity: 0.34;
  cursor: not-allowed;
}

.offering::after {
  content: "✦";
  position: absolute;
  top: 13px;
  right: 15px;
  color: var(--pink);
  font-size: 15px;
}

.offering h3 {
  font-size: 1.65rem;
  font-weight: 500;
  line-height: 0.95;
}

.offering p {
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.5;
}

.offering-exchange {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding-top: 16px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.offering-exchange b {
  color: var(--red);
  font-weight: 500;
}

.offering-exchange i {
  color: var(--pink);
  font-style: normal;
}

.offering-locked {
  margin-top: 8px;
  color: var(--red);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ---------- rest / treasure ---------- */

.rest-screen,
.treasure-screen {
  min-height: 100dvh;
}

.rest-wrap,
.treasure-wrap {
  width: min(900px, calc(100% - 32px));
  margin: 0 auto;
  padding: clamp(40px, 9vh, 100px) 0 50px;
  text-align: center;
}

.rest-glyph {
  color: var(--blue);
  font-family: var(--serif);
  font-size: 4.8rem;
  line-height: 0.8;
}

.rest-wrap h1,
.treasure-wrap h1 {
  margin-top: 12px;
  font-size: clamp(3rem, 6vw, 5.4rem);
  font-weight: 500;
  letter-spacing: -0.05em;
  line-height: 0.84;
}

.rest-wrap > p,
.treasure-wrap > p {
  max-width: 560px;
  margin: 15px auto 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.14rem;
  font-style: italic;
  line-height: 1.45;
}

.rest-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin-top: 32px;
}

.rest-choice {
  width: 230px;
  padding: 17px;
  border: 1px solid var(--line);
  color: var(--cream);
  background: var(--panel);
  text-align: left;
  transition: border-color 150ms ease, transform 150ms ease;
}

.rest-choice:hover {
  border-color: var(--blue);
  transform: translateY(-2px);
}

.rest-choice strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 500;
  line-height: 1;
}

.rest-choice span {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.45;
}

.treasure-glyph {
  color: var(--gold);
  font-family: var(--serif);
  font-size: 5rem;
  line-height: 0.8;
}

.treasure-reveal {
  width: min(480px, 100%);
  margin: 25px auto 0;
  padding: 20px;
  border: 1px solid rgba(216, 177, 108, 0.3);
  background: rgba(216, 177, 108, 0.04);
  text-align: left;
}

.treasure-reveal .result-line {
  font-size: 12.5px;
}

.treasure-actions {
  display: flex;
  justify-content: center;
  margin-top: 28px;
}

/* ---------- act intro ---------- */

.act-intro-screen {
  position: relative;
  display: grid;
  min-height: 100dvh;
  padding: 26px;
  place-items: center;
  overflow: hidden;
}

.act-intro-screen::before {
  content: attr(data-roman);
  position: absolute;
  top: 50%;
  left: 50%;
  color: rgba(239, 230, 210, 0.03);
  font-family: var(--serif);
  font-size: min(82vw, 900px);
  font-weight: 600;
  line-height: 0.6;
  transform: translate(-50%, -50%);
}

.act-intro-card {
  position: relative;
  z-index: 1;
  width: min(720px, 100%);
  padding: clamp(30px, 6vw, 64px);
  border: 1px solid var(--line-strong);
  background: rgba(20, 17, 21, 0.84);
  text-align: center;
  box-shadow: var(--shadow);
}

.act-intro-card h1 {
  margin-top: 12px;
  font-size: clamp(3.3rem, 8vw, 6rem);
  font-weight: 500;
  letter-spacing: -0.055em;
  line-height: 0.8;
}

.act-intro-card h1 em {
  color: var(--muted);
  font-style: italic;
  font-weight: 400;
}

.act-intro-card p {
  max-width: 460px;
  margin: 17px auto 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.17rem;
  font-style: italic;
  line-height: 1.45;
}

.act-intro-boss {
