/* ---------- endings ---------- */

.end-screen {
  position: relative;
  display: flex;
  min-height: 100dvh;
  padding: max(30px, env(safe-area-inset-top)) 22px 44px;
  overflow: hidden;
}

.end-screen::before {
  content: attr(data-word);
  position: absolute;
  top: 48%;
  left: 50%;
  color: rgba(239, 230, 210, 0.027);
  font-family: var(--serif);
  font-size: min(24vw, 300px);
  font-weight: 600;
  letter-spacing: -0.06em;
  line-height: 0.7;
  text-transform: uppercase;
  transform: translate(-50%, -50%);
  white-space: nowrap;
}

.end-wrap {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(230px, 0.7fr) minmax(0, 1.3fr);
  gap: clamp(28px, 5vw, 72px);
  align-items: center;
  width: min(1040px, 100%);
  margin: auto;
}

.end-art {
  position: relative;
  aspect-ratio: 3 / 4;
  border: 1px solid var(--line-strong);
  background: var(--panel);
  overflow: hidden;
}

.end-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 18%;
  filter: grayscale(0.3) saturate(0.8) brightness(0.75);
}

.end-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 48%, rgba(11, 9, 11, 0.9));
}

.end-art-label {
  position: absolute;
  z-index: 2;
  right: 17px;
  bottom: 15px;
  left: 17px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.end-copy h1 {
  margin-top: 9px;
  font-size: clamp(3.4rem, 7vw, 6rem);
  font-weight: 500;
  letter-spacing: -0.06em;
  line-height: 0.8;
}

.end-copy h1 em {
  color: var(--red);
  font-style: italic;
  font-weight: 400;
}

.end-screen.clear .end-copy h1 em {
  color: var(--gold);
}

.end-lede {
  max-width: 520px;
  margin-top: 17px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.18rem;
  font-style: italic;
  line-height: 1.45;
}

.end-ash {
