  gap: 12px;
  margin-top: 24px;
}

.end-ash strong {
  color: var(--gold);
  font-family: var(--serif);
  font-size: 3.4rem;
  font-weight: 500;
  line-height: 0.8;
}

.end-ash span {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.end-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-top: 25px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
