/* The checkerboard map. */

import { CHARACTERS } from "../data/characters.js";
import { ACTS, CHARMS } from "../data/enemies.js";
import {
  charStyle, metaSummary, nodeType, NODE_TYPES, portrait, renderRunBar,
} from "./shared.js";

function nodeClass(node, run, available) {
  const isCurrent = node.id === run.currentNode;
  const canEnter = available.has(node.id);
  const classes = ["map-node"];
  if (node.type === "boss") classes.push("boss");
  if (node.type === "start") classes.push("start");
  if (isCurrent) classes.push("current");
  else if (canEnter) classes.push("available");
  else if (node.done) classes.push("done");
  else classes.push("locked");
  if (node.done) classes.push("done");
  return classes.join(" ");
}

export function renderMap(game) {
  const run = game.run;
  if (!run) return "";
  const char = CHARACTERS[run.char];
  const act = ACTS[run.act];
  const available = new Set(run.available);
  const current = run.map.nodes.find((n) => n.id === run.currentNode);
  const nodesById = Object.fromEntries(run.map.nodes.map((n) => [n.id, n]));

  const tiles = [];
  for (let row = 7; row >= 0; row -= 1) {
    for (let col = 0; col < 5; col += 1) {
      const dark = (row + col) % 2 === 0;
      tiles.push(`<span class="map-tile ${dark ? "dark" : "light"}"></span>`);
    }
  }

  const lines = [];
  for (const node of run.map.nodes) {
    for (const targetId of node.conn || []) {
      const target = nodesById[targetId];
      if (!target) continue;
      const x1 = (node.col + 0.5) * 100;
      const y1 = (7 - node.row + 0.5) * 100;
      const x2 = (target.col + 0.5) * 100;
      const y2 = (7 - target.row + 0.5) * 100;
      let lineClass = "map-line";
      if (node.id === run.currentNode) lineClass += " active";
      else if (node.done) lineClass += " done";
      lines.push(`<line class="${lineClass}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" />`);
    }
  }

  const nodeMarkup = run.map.nodes.map((node) => {
    const info = nodeType(node.type);
    const isAvailable = available.has(node.id);
    const isCurrent = node.id === run.currentNode;
    const cls = nodeClass(node, run, available);
    const disabled = !isAvailable;
    const label = isAvailable || isCurrent || node.type === "boss" ? `<span class="node-label">${info.label}</span>` : "";
    const aria = `${info.label}${isAvailable ? ". Available" : isCurrent ? ". Current" : node.done ? ". Cleared" : ". Locked"}`;
    return `<button type="button" class="${cls}" data-type="${node.type}" style="left:${(node.col + 0.5) * 20}%;top:${(7 - node.row + 0.5) * 12.5}%" data-action="${isAvailable ? "enterNode" : "noop"}" data-node="${node.id}" title="${info.label}" aria-label="${aria}" ${disabled ? "disabled" : ""}>
      <span class="node-icon">${info.icon}</span>
      ${label}
    </button>`;
  }).join("");

  const boons = run.boons.length
    ? run.boons.map((b) => `<div class="boon-item"><span><strong>${b.name}</strong> — ${b.boon}</span></div>`).join("")
    : `<p class="empty-note">No offerings made. The stone is patient.</p>`;

  const charms = run.charms.length
    ? run.charms.map((key) => `<div class="charm-item"><span><strong>${CHARMS[key].name}</strong> — ${CHARMS[key].desc}</span></div>`).join("")
    : `<p class="empty-note">No charms collected yet.</p>`;

  const legend = ["battle", "elite", "shop", "event", "special", "rest", "treasure", "boss"].map((type) => {
    const info = NODE_TYPES[type];
    return `<div class="legend-item"><span class="legend-icon" style="--legend:${info.color}">${info.icon}</span>${info.label}</div>`;
  }).join("");

  const next = run.available.map((id) => nodesById[id]).filter(Boolean);
  const nextLine = next.length
    ? next.map((n) => nodeType(n.type).label).filter((v, i, a) => a.indexOf(v) === i).join(" · ")
    : "The boss waits.";

  return `<main class="map-screen" style="${charStyle(run.char)}">
    ${renderRunBar(game)}
    <div class="map-page">
      <aside class="map-aside left">
        <div class="run-portrait-card">
          ${portrait(game, run.char, run.outfit)}
          <div class="run-portrait-copy">
            <h2>${char.name}</h2>
            <span>${char.epithet}</span>
            <small>${char.passive.name}<br />${char.style}</small>
          </div>
        </div>
        <div class="panel">
          <div class="panel-head"><span>THE CLIMB</span><strong>${act.roman} / III</strong></div>
          <div class="panel-body">
            <div class="stat-row"><span>Health</span><strong>${run.hp} / ${run.maxHp}</strong></div>
            <div class="stat-row"><span>Gold</span><strong class="gold">${run.gold}g</strong></div>
            <div class="stat-row"><span>Deck</span><strong>${run.deck.length} cards</strong></div>
            <div class="stat-row"><span>Charms</span><strong>${run.charms.length}</strong></div>
            <div class="stat-row"><span>Rooms cleared</span><strong>${run.roomsCleared}</strong></div>
          </div>
        </div>
        <div class="panel">
          <div class="panel-head"><span>OFFERINGS</span><strong>${run.boons.length}</strong></div>
          <div class="panel-body"><div class="boon-list">${boons}</div></div>
        </div>
        <div class="panel">
          <div class="panel-head"><span>CHARMS</span><strong>${run.charms.length}</strong></div>
          <div class="panel-body"><div class="charm-list">${charms}</div></div>
        </div>
      </aside>

      <section class="map-main">
        <div class="map-heading">
          <div class="eyebrow no-line" style="justify-content:center">ACT ${act.roman} · THE ${String(act.name).replace(/^The /, "").toUpperCase()}</div>
          <h1>The <em>${act.name.replace(/^The /, "")}</em></h1>
          <p>${act.subtitle}</p>
        </div>
        <div class="map-board-wrap">
          <div class="map-board">
            <div class="map-grid">${tiles.join("")}</div>
            <svg class="map-lines" viewBox="0 0 500 800" preserveAspectRatio="none" aria-hidden="true">${lines.join("")}</svg>
            ${nodeMarkup}
          </div>
        </div>
        <div class="board-caption">
          <span>${nextLine}</span>
          <span>${run.currentRow} / 7 rooms climbed</span>
        </div>
      </section>

      <aside class="map-aside right">
        <div class="act-panel" data-roman="${act.roman}">
          <div class="eyebrow no-line">CURRENT ACT</div>
          <h3>${act.name}</h3>
          <p>${act.subtitle}</p>
          <div class="act-boss">${act.boss}</div>
        </div>
        <div class="panel">
          <div class="panel-head"><span>THE BOARD</span><strong>READ THE TILES</strong></div>
          <div class="panel-body">
            <div class="legend-list">${legend}</div>
          </div>
        </div>
        <div class="panel">
          <div class="panel-head"><span>YOUR MOVE</span><strong>${next.length} OPEN</strong></div>
          <div class="panel-body">
            <p class="empty-note">Pick a lit tile one row above you. The board only lets you climb on the diagonal or straight up. Every choice is a room you will not see again.</p>
          </div>
        </div>
      </aside>
    </div>
  </main>`;
}

/* Combat screen. */

import { CHARACTERS } from "../data/characters.js";
import { CARDS } from "../data/cards.js";
import { ACTS, moveIntent, STATUS_INFO } from "../data/enemies.js";
import {
  cardMarkup, charStyle, hpBar, lastLogs, renderRunBar, staminaPips, statusChips,
} from "./shared.js";

function enemyCard(enemy, combat, pendingDef) {
  const taunts = combat.enemies.filter((e) => e.alive && e.taunt);
  const targetable = !!pendingDef
    && pendingDef.target === "enemy"
    && enemy.alive
    && combat.phase === "player"
    && !combat.ended
    && (!taunts.length || enemy.taunt);
  const move = enemy.alive ? enemy.moves[enemy.pattern[enemy.moveIndex % enemy.pattern.length]] : null;
  const intent = move ? moveIntent(move, enemy) : "";
  const hostile = move && (move.dmg || move.status || move.status2 || move.strength || move.strengthAll || move.summon || move.taunt);
  const status = statusChips({
    strength: enemy.strength,
    bleed: enemy.statuses.bleed,
    book: enemy.statuses.book,
    weak: enemy.statuses.weak,
    vulnerable: enemy.statuses.vulnerable,
  });
  const blockChip = enemy.block > 0 ? `<div class="shield-row"><span class="shield-chip">${enemy.block} Block</span></div>` : "";
  const tags = [
    ...enemy.tags,
    enemy.taunt ? "Taunting" : "",
    enemy.enraged ? "Phase II" : "",
    enemy.summoned ? "Summoned" : "",
  ].filter(Boolean).map((tag) => `<span class="enemy-tag">${tag}</span>`).join("");

  const inner = `
    ${enemy.boss ? `<div class="boss-ribbon">FINAL OBSTACLE</div>` : ""}
    <div class="enemy-top">
      <span class="enemy-crest" style="--enemy:${enemy.color}">${enemy.crest}</span>
      <div class="enemy-title">
        <h3>${enemy.name}</h3>
        <p>${enemy.boss ? "BOSS" : enemy.minion ? "MINION" : "ENEMY"} · ${enemy.hp} / ${enemy.maxHp} HP</p>
      </div>
      <div class="intent-chip ${hostile ? "hostile" : ""}">
        <span>${enemy.alive ? "INTENT" : "OUT"}</span>
        <strong>${enemy.alive ? intent : "—"}</strong>
      </div>
    </div>
    <div class="enemy-hp">
      ${hpBar(enemy.hp, enemy.maxHp, "enemy")}
    </div>
    ${blockChip}
    <div class="enemy-statuses">${status}</div>
    <div class="enemy-tags">${tags}</div>
    <p class="enemy-flavor">${enemy.flavor}</p>`;

  if (!enemy.alive) {
    return `<article class="enemy-card dead" style="--enemy:${enemy.color}">
      <div class="enemy-title"><h3>${enemy.name}</h3><p>DEFEATED</p></div>
    </article>`;
  }

  if (targetable) {
    return `<button type="button" class="enemy-card targetable ${enemy.taunt ? "taunting" : ""} ${enemy.boss ? "boss" : ""}" style="--enemy:${enemy.color}" data-action="targetEnemy" data-uid="${enemy.uid}">
      ${inner}
    </button>`;
  }
  return `<article class="enemy-card ${enemy.taunt ? "taunting" : ""} ${enemy.boss ? "boss" : ""}" style="--enemy:${enemy.color}">
    ${inner}
  </article>`;
}

export function renderCombat(game, ui) {
  const combat = game.combat;
  if (!combat) return "";
  const run = game.run;
  const char = CHARACTERS[run.char];
  const player = combat.player;
  const act = ACTS[run.act];
  const pendingCard = combat.pendingCard
    ? combat.hand.find((c) => c.uid === combat.pendingCard)
    : null;
  const pendingDef = pendingCard ? CARDS[pendingCard.key] : null;
  const taunts = combat.enemies.filter((e) => e.alive && e.taunt);
  const canAct = combat.phase === "player" && !combat.ended;
  const playedStatuses = {
    strength: player.strength,
    weak: player.weak,
    vulnerable: player.vulnerable,
    bleed: player.bleed,
  };

  const enemies = combat.enemies.map((enemy) => enemyCard(enemy, combat, pendingDef)).join("");

  const taco = combat.taco
    ? `<div class="taco-card ${combat.taco.alive ? "" : "down"}">
        <div class="taco-head"><span>TACO · ${combat.taco.alive ? "SUMMON" : "DOWN"}</span><strong>${combat.taco.hp} / ${combat.taco.maxHp}</strong></div>
        ${hpBar(combat.taco.hp, combat.taco.maxHp, "taco")}
        <div class="taco-meta"><span>${combat.taco.block ? `${combat.taco.block} BLOCK` : "INTERCEPTS HITS"}</span><span>BITE ${combat.taco.attack}</span></div>
      </div>`
    : "";

  const hand = combat.hand.map((card) => {
    const def = CARDS[card.key];
    const unplayable = !canAct || combat.stamina < def.cost;
    return cardMarkup(card, {
      action: "card",
      selected: combat.pendingCard === card.uid,
      unplayable,
      disabled: false,
    });
  }).join("");

  const drawCount = combat.drawPile.length;
  const discardCount = combat.discardPile.length;
  const exhaustCount = combat.exhaustPile.length;

  const targetPrompt = pendingDef
    ? `<div class="target-prompt"><span>Choose a target for ${pendingDef.name}</span><button type="button" data-action="cancelTarget">Cancel</button></div>`
    : "";

  const enemyHint = taunts.length && canAct ? "TAUNT ACTIVE" : "CHOOSE TARGET";
  const logToggle = ui.logOpen ? "active" : "";

  return `<main class="combat-screen" style="${charStyle(run.char)}">
    ${renderRunBar(game, { combat: true })}
    <div class="battlefield ${ui.logOpen ? "with-log" : ""}">
      <section class="player-column">
        <div class="combat-player">
          <div class="combat-player-art">
            ${portraitForCombat(game)}
          </div>
          <div class="combat-player-name"><h2>${char.name}</h2><span>${player.hp} HP</span></div>
          <div class="combat-player-body">
            <div class="hp-line"><span>VITALITY</span><strong>${player.hp} <em>/ ${player.maxHp}</em></strong></div>
            ${hpBar(player.hp, player.maxHp, "player")}
            <div class="shield-row">
              ${player.block ? `<span class="shield-chip">${player.block} BLOCK</span>` : ""}
              ${player.overshield ? `<span class="shield-chip">${player.overshield} OVERSHIELD</span>` : ""}
            </div>
            <div class="stamina-block">
              <div class="stamina-label"><span>STAMINA</span><strong>${combat.stamina} / ${combat.maxStamina}</strong></div>
              ${staminaPips(combat.stamina, combat.maxStamina)}
            </div>
            <div class="player-stats">
              <div class="player-stat"><span>STR</span><strong>${player.strength}</strong></div>
              <div class="player-stat"><span>CRIT</span><strong>${Math.round((player.crit + combat.critBonus) * 100)}%</strong></div>
              <div class="player-stat"><span>CRIT DMG</span><strong>${Math.round(player.critDamage * 100)}%</strong></div>
              <div class="player-stat"><span>DRAW</span><strong>${combat.drawCount}</strong></div>
            </div>
            ${statusChips(playedStatuses, { crit: Math.round(combat.critBonus * 100) })}
          </div>
        </div>
        <div class="passive-strip"><strong>${char.passive.name}</strong><p>${char.passive.text}</p></div>
        ${taco}
      </section>

      <section class="enemy-column">
        <div class="combat-location"><span>${act.name} · ROOM ${run.roomsCleared + 1}</span><span>${combat.ended ? "BOARD CLEAR" : canAct ? "YOUR TURN" : "ENEMY TURN"}</span></div>
        <div class="enemy-grid">${enemies}</div>
      </section>

      <aside class="combat-side">
        <div class="combat-side-head"><span>THE BOARD REMEMBERS</span><strong>${combat.ended ? "END" : "LIVE"}</strong></div>
        <div class="combat-log" data-combat-log>${lastLogs(game, 28)}</div>
        <div class="side-summary">
          <div class="side-summary-row"><span>Draw pile</span><strong>${drawCount}</strong></div>
          <div class="side-summary-row"><span>Discard</span><strong>${discardCount}</strong></div>
          <div class="side-summary-row"><span>Exhausted</span><strong>${exhaustCount}</strong></div>
          <div class="side-summary-row"><span>Enemies left</span><strong>${combat.enemies.filter((e) => e.alive).length}</strong></div>
        </div>
      </aside>
    </div>

    <section class="hand-zone">
      <div class="hand-top">
        <div class="hand-meta"><span>STAMINA <strong>${combat.stamina}/${combat.maxStamina}</strong></span><span>HAND <strong>${combat.hand.length}</strong></span><span>${taunts.length ? "TAUNT" : "TURN " + combat.turn}</span></div>
        ${targetPrompt || (canAct ? `<span class="muted" style="font-family:var(--mono);font-size:7px;letter-spacing:.08em;text-transform:uppercase">${enemyHint}</span>` : "")}
      </div>
      <div class="hand-layout">
        <div class="hand-scroll">${hand || `<span class="empty-note">No cards in hand. End the turn.</span>`}</div>
        <div class="end-turn-wrap">
          <button type="button" class="end-turn" data-action="endTurn" ${!canAct ? "disabled" : ""}>End turn<small>E</small></button>
          <span class="end-turn-meta">${canAct ? "pay the board" : "wait"}</span>
        </div>
      </div>
    </section>
  </main>`;
}

function portraitForCombat(game) {
  const run = game.run;
  const outfit = CHARACTERS[run.char].outfits[run.outfit] || CHARACTERS[run.char].outfits[0];
  return `<img class="portrait" src="${outfit.file}" alt="${CHARACTERS[run.char].name}" onerror="this.classList.add('missing')" />`;
}

/* Reward and shop screens. */

import { CARDS, RARITY } from "../data/cards.js";
import { CHARMS, ACTS } from "../data/enemies.js";
import { cardMarkup, charStyle, renderRunBar } from "./shared.js";

export function renderReward(game) {
  const reward = game.pending?.reward;
  if (!reward) return "";
  const char = game.run.char;
  const heading = reward.boss ? "The act is <em>closed.</em>" : reward.elite ? "The elite is <em>done.</em>" : "The board is <em>clear.</em>";
  const kicker = reward.boss ? "BOSS DEFEATED" : reward.elite ? "ELITE DEFEATED" : "BATTLE WON";
  const cards = reward.cards.map((card, index) => cardMarkup(card, {
    action: "chooseReward",
    index,
    className: "reward-card",
  })).join("");
  const charm = reward.charm
    ? `<div class="reward-charm">Charm acquired · <strong>${reward.charm.name}</strong> — ${reward.charm.desc}</div>`
    : "";
  const act = ACTS[game.run.act];

  return `<main class="reward-screen" style="${charStyle(char)}">
    ${renderRunBar(game)}
    <div class="reward-wrap">
      <header class="reward-head">
        <div class="eyebrow no-line" style="justify-content:center">${kicker} · ACT ${act.roman}</div>
        <h1>${heading}</h1>
        <div class="reward-summary">
          <span>Gold <strong>+${reward.gold}</strong></span>
          <span>Deck <strong>${game.run.deck.length}</strong></span>
          <span>HP <strong>${game.run.hp}/${game.run.maxHp}</strong></span>
          ${reward.boss ? "<span>Next act <strong>imminent</strong></span>" : ""}
        </div>
        ${charm}
      </header>
      <div class="reward-cards">${cards}</div>
      <div class="reward-actions">
        <button type="button" class="btn btn-ghost" data-action="skipReward">Take no card</button>
      </div>
    </div>
  </main>`;
}

function shopCard(item, index) {
  const def = CARDS[item.key];
  const rarity = RARITY[def.rarity];
  return `<div class="shop-item ${item.sold ? "sold" : ""}" style="--rarity:${rarity.color}">
    ${cardMarkup({ key: item.key, uid: `shop-${index}`, upgraded: false })}
    <div class="shop-price"><span>${item.sold ? "SOLD" : rarity.label}</span><button type="button" class="btn btn-small" data-action="buyShopCard" data-index="${index}">${item.sold ? "Sold" : `${item.price}g`}</button></div>
  </div>`;
}

export function renderShop(game) {
  const shop = game.pending?.shop;
  if (!shop) return "";
  const mode = shop.mode;
  const cards = shop.cards.map(shopCard).join("");
  const charm = shop.charm
    ? `<div class="shop-charm">
        <div class="shop-charm-head"><span>Charm</span><strong>${CHARMS[shop.charm.key].name}</strong></div>
        <p>${CHARMS[shop.charm.key].desc}</p>
        <button type="button" class="btn btn-small" data-action="buyShopCharm" ${shop.charm.sold ? "disabled" : ""}>${shop.charm.sold ? "Sold" : `${shop.charm.price}g · take it`}</button>
      </div>`
    : "";

  const pickList = game.run.deck.map((card) => {
    const def = CARDS[card.key];
    const isUpgrade = mode === "upgrade";
    const disabled = isUpgrade
      ? card.upgraded || game.run.gold < shop.upgradeCost
      : game.run.deck.length <= 5 || game.run.gold < shop.removeCost;
    return `<button type="button" class="deck-pick" data-action="${isUpgrade ? "shopUpgrade" : "shopRemove"}" data-uid="${card.uid}" ${disabled ? "disabled" : ""}>
      <span><strong>${def.name}${card.upgraded ? " +" : ""}</strong></span><span>${isUpgrade ? (card.upgraded ? "honing max" : `${shop.upgradeCost}g`) : `${shop.removeCost}g`}</span>
    </button>`;
  }).join("");

  return `<main class="location-screen shop-screen" style="${charStyle(game.run.char)}">
    ${renderRunBar(game)}
    <div class="location-wrap">
      <header class="location-head">
        <div>
          <div class="eyebrow">OPTIONAL · BUT TEMPTING</div>
          <h1>The <em>Tuck Shop.</em></h1>
          <p>Cards, cures, and one deeply suspicious charm. The shopkeeper does not look up from her crossword.</p>
        </div>
        <div class="location-gold"><strong>${game.run.gold}</strong><span>gold</span></div>
      </header>

      <div class="shop-layout">
        <section>
          <div class="shop-section-head"><span>CARDS FOR SALE</span><span>${shop.cards.filter((c) => !c.sold).length} remaining</span></div>
          <div class="shop-cards">${cards}</div>
          ${charm}
          ${mode ? `<div class="deck-picker">
            <div class="deck-picker-head"><span>${mode === "upgrade" ? "Choose a card to hone · 55g" : "Choose a card to forget · 45g"}</span><button type="button" class="btn btn-small" data-action="shopMode" data-mode="${mode}">Cancel</button></div>
            <div class="deck-picker-list">${pickList}</div>
          </div>` : ""}
        </section>

        <aside class="shop-services">
          <div class="shop-section-head"><span>SERVICES</span><span>THE SMALL PRINT</span></div>
          <button type="button" class="service-card" data-action="shopHeal" ${shop.healUsed || game.run.gold < shop.healCost ? "disabled" : ""}>
            <span class="service-copy"><strong>Patch Up</strong><span>${shop.healUsed ? "Already used in this shop." : "Heal 35% of max HP."}</span></span>
            <span class="service-price">${shop.healUsed ? "USED" : `${shop.healCost}g`}</span>
          </button>
          <button type="button" class="service-card ${mode === "upgrade" ? "active" : ""}" data-action="shopMode" data-mode="upgrade" ${game.run.gold < shop.upgradeCost ? "disabled" : ""}>
            <span class="service-copy"><strong>Hone a Card</strong><span>Permanently upgrade one card for this run.</span></span>
            <span class="service-price">${shop.upgradeCost}g</span>
          </button>
          <button type="button" class="service-card ${mode === "remove" ? "active" : ""}" data-action="shopMode" data-mode="remove" ${game.run.deck.length <= 5 || game.run.gold < shop.removeCost ? "disabled" : ""}>
            <span class="service-copy"><strong>Forget a Card</strong><span>Remove a card from your deck for this run.</span></span>
            <span class="service-price">${shop.removeCost}g</span>
          </button>
          <button type="button" class="service-card" data-action="leaveShop">
            <span class="service-copy"><strong>Leave the shop</strong><span>Climb on. The staircase is not getting shorter.</span></span>
            <span class="service-price">→</span>
          </button>
        </aside>
      </div>
    </div>
  </main>`;
}

/* Events, offering stones, rest, treasure, and act transitions. */

import { CARDS } from "../data/cards.js";
import { ACTS, CHARMS } from "../data/enemies.js";
import { SPECIALS } from "../data/events.js";
import { charStyle, renderRunBar } from "./shared.js";

function resultLines(lines) {
  return lines.map((line) => `<div class="result-line">${line}</div>`).join("");
}

export function renderEvent(game) {
  const pending = game.pending?.event;
  if (!pending) return "";
  const { event, node } = pending;
  const isResult = !!pending.result;
  const choices = isResult
    ? `<div class="result-box">
        <h2>THE BOARD TURNS</h2>
        <div class="result-lines">${resultLines(pending.result.lines.length ? pending.result.lines : ["Nothing changes. The room remembers you anyway."])}</div>
        <div class="modal-actions"><button type="button" class="btn btn-primary" data-action="leaveEvent">Continue the climb</button></div>
      </div>`
    : `<div class="choice-list">
        ${event.choices.map((choice, index) => `<button type="button" class="choice ${choice.tone}" data-action="eventChoice" data-index="${index}">
          <span class="choice-mark">${choice.tone === "good" ? "✦" : choice.tone === "pact" ? "☠" : "·"}</span>
          <span class="choice-copy"><strong>${choice.label}</strong><span>${choice.detail}</span></span>
          <span class="choice-tag">${choice.tone === "good" ? "BOON" : choice.tone === "pact" ? "PACT" : "SMALL"}</span>
        </button>`).join("")}
      </div>`;

  return `<main class="event-screen" data-glyph="?" style="${charStyle(game.run.char)}">
    ${renderRunBar(game)}
    <div class="event-stage">
      <div class="event-kicker">RANDOM EVENT · ${isResult ? "CONSEQUENCE" : "A ROOM OFF THE BOARD"}</div>
      <h1 class="event-title">${event.title}</h1>
      <p class="event-body">${isResult ? `${pending.result.choice.label}. The room makes a sound like a page turning.` : event.body}</p>
      ${choices}
    </div>
  </main>`;
}

export function renderSpecial(game) {
  const pending = game.pending?.special;
  if (!pending) return "";
  const isResult = !!pending.result;
  const offerings = SPECIALS.offerings.map((offering) => {
    const can = offering.requires(game.run) && !isResult;
    return `<button type="button" class="offering" data-action="${can ? "takeOffering" : "noop"}" data-offering="${offering.id}" ${can ? "" : "disabled"}>
      <h3>${offering.name}</h3>
      <p>${offering.desc}</p>
      <div class="offering-exchange"><b>OFFER: ${offering.offer}</b><i>→</i><span>${offering.boon}</span></div>
      ${offering.requires(game.run) ? "" : `<div class="offering-locked">${offering.cannot}</div>`}
    </button>`;
  }).join("");

  return `<main class="special-screen" data-glyph="✦" style="${charStyle(game.run.char)}">
    ${renderRunBar(game)}
    <div class="special-stage">
      <div class="event-kicker">SPECIAL SPACE · THE OFFERING STONE</div>
      <h1 class="special-title">${SPECIALS.title}</h1>
      <p class="special-lede">${SPECIALS.body}</p>
      ${isResult
        ? `<div class="result-box">
            <h2>THE STONE ACCEPTS</h2>
            <div class="result-lines">${resultLines(pending.result.lines)}</div>
            <div class="modal-actions"><button type="button" class="btn btn-primary" data-action="leaveSpecial">Carry the boon onward</button></div>
          </div>`
        : `<div class="offerings">${offerings}</div>
           <div class="modal-actions"><button type="button" class="btn btn-ghost" data-action="leaveSpecial">Walk away untouched</button></div>`}
    </div>
  </main>`;
}

export function renderRest(game) {
  const rest = game.pending?.rest;
  if (!rest) return "";
  const deckPicker = rest.mode === "upgrade"
    ? `<div class="deck-picker" style="max-width:720px;margin:22px auto 0;text-align:left">
        <div class="deck-picker-head"><span>Choose a card to sharpen</span><button type="button" class="btn btn-small" data-action="restUpgradeMode">Cancel</button></div>
        <div class="deck-picker-list">
          ${game.run.deck.map((card) => {
            const def = CARDS[card.key];
            return `<button type="button" class="deck-pick" data-action="restUpgrade" data-uid="${card.uid}" ${card.upgraded ? "disabled" : ""}>
              <span><strong>${def.name}${card.upgraded ? " +" : ""}</strong></span><span>${card.upgraded ? "MAX" : "SHARPEN"}</span>
            </button>`;
          }).join("")}
        </div>
      </div>`
    : "";

  const body = rest.done
    ? `<div class="result-box" style="max-width:640px;margin:26px auto 0;text-align:left">
        <h2>YOU REST</h2>
        <div class="result-lines">${resultLines(rest.lines)}</div>
        <div class="modal-actions"><button type="button" class="btn btn-primary" data-action="leaveRest">Continue the climb</button></div>
      </div>`
    : `<div class="rest-actions">
        <button type="button" class="rest-choice" data-action="restHeal">
          <strong>Sleep badly</strong>
          <span>Heal 35% of your max HP. Dream of the staircase.</span>
        </button>
        <button type="button" class="rest-choice" data-action="restUpgradeMode">
          <strong>Sharpen a card</strong>
          <span>Permanently upgrade one card for the rest of this run.</span>
        </button>
      </div>
      <div class="btn-row" style="justify-content:center;margin-top:22px"><button type="button" class="btn btn-ghost" data-action="leaveRest">Leave the room</button></div>`;

  return `<main class="rest-screen" style="${charStyle(game.run.char)}">
    ${renderRunBar(game)}
    <div class="rest-wrap">
      <div class="rest-glyph">☾</div>
      <h1>The <em>Quiet Room.</em></h1>
      <p>No bells. No ink. Just a cot, a candle, and enough time for one terrible idea.</p>
      ${deckPicker}
      ${body}
    </div>
  </main>`;
}

export function renderTreasure(game) {
  const treasure = game.pending?.treasure;
  if (!treasure) return "";
  return `<main class="treasure-screen" style="${charStyle(game.run.char)}">
    ${renderRunBar(game)}
    <div class="treasure-wrap">
      <div class="treasure-glyph">◈</div>
      <h1>A <em>small fortune.</em></h1>
      <p>The chest is not locked. It has never been locked. That is somehow worse.</p>
      <div class="treasure-reveal">
        <div class="result-lines">${treasure.lines.map((line) => `<div class="result-line">${line}</div>`).join("")}</div>
        ${treasure.charmKey ? `<div class="result-line" style="margin-top:9px;color:var(--green)">${CHARMS[treasure.charmKey].name} — ${CHARMS[treasure.charmKey].desc}</div>` : ""}
      </div>
      <div class="treasure-actions"><button type="button" class="btn btn-primary" data-action="leaveTreasure">Take it all and climb</button></div>
    </div>
  </main>`;
}

export function renderActIntro(game) {
  const intro = game.pending?.actIntro;
  if (!intro) return "";
  const act = ACTS[game.run.act];
  return `<main class="act-intro-screen" data-roman="${act.roman}" style="${charStyle(game.run.char)}">
    <div class="act-intro-card">
      <div class="eyebrow no-line" style="justify-content:center">ACT ${act.roman} OF III</div>
      <h1>${act.name.replace(/^The /, "The ").replace(/^(.*)$/, "$1")}<br /><em>${act.roman}.</em></h1>
      <p>${act.subtitle}</p>
      <div class="act-intro-boss">Next boss · ${act.boss}</div>
      ${intro.healed ? `<div class="act-intro-heal">Between acts, you recover ${intro.healed} HP.</div>` : ""}
      <div class="modal-actions" style="justify-content:center"><button type="button" class="btn btn-primary" data-action="continueActIntro">Climb higher</button></div>
    </div>
  </main>`;
}

