/* ---------- endings ---------- */

.end-screen {
  position: relative;
  display: flex;
  min-height: 100dvh;
  padding: max(30px, env(safe-area-inset-top)) 22px 44px;
  overflow: hidden;
}

.end-screen::before {
  content: attr(data-word);
  position: absolute;
  top: 48%;
  left: 50%;
  color: rgba(239, 230, 210, 0.027);
  font-family: var(--serif);
  font-size: min(24vw, 300px);
  font-weight: 600;
  letter-spacing: -0.06em;
  line-height: 0.7;
  text-transform: uppercase;
  transform: translate(-50%, -50%);
  white-space: nowrap;
}

.end-wrap {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(230px, 0.7fr) minmax(0, 1.3fr);
  gap: clamp(28px, 5vw, 72px);
  align-items: center;
  width: min(1040px, 100%);
  margin: auto;
}

.end-art {
  position: relative;
  aspect-ratio: 3 / 4;
  border: 1px solid var(--line-strong);
  background: var(--panel);
  overflow: hidden;
}

.end-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 18%;
  filter: grayscale(0.3) saturate(0.8) brightness(0.75);
}

.end-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 48%, rgba(11, 9, 11, 0.9));
}

.end-art-label {
  position: absolute;
  z-index: 2;
  right: 17px;
  bottom: 15px;
  left: 17px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.end-copy h1 {
  margin-top: 9px;
  font-size: clamp(3.4rem, 7vw, 6rem);
  font-weight: 500;
  letter-spacing: -0.06em;
  line-height: 0.8;
}

.end-copy h1 em {
  color: var(--red);
  font-style: italic;
  font-weight: 400;
}

.end-screen.clear .end-copy h1 em {
  color: var(--gold);
}

.end-lede {
  max-width: 520px;
  margin-top: 17px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.18rem;
  font-style: italic;
  line-height: 1.45;
}

.end-ash {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-top: 24px;
}

.end-ash strong {
  color: var(--gold);
  font-family: var(--serif);
  font-size: 3.4rem;
  font-weight: 500;
  line-height: 0.8;
}

.end-ash span {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.end-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-top: 25px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.end-stat span {
  display: block;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.end-stat strong {
  display: block;
  margin-top: 4px;
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: 1.45rem;
  font-weight: 500;
  line-height: 1;
}

.end-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 25px;
}

/* ---------- prestige result ---------- */

.prestige-screen {
  min-height: 100dvh;
  padding: 32px 20px 50px;
}

.prestige-wrap {
  width: min(980px, 100%);
  margin: 0 auto;
  text-align: center;
}

.prestige-wrap h1 {
  margin-top: 10px;
  font-size: clamp(3.2rem, 7vw, 6.2rem);
  font-weight: 500;
  letter-spacing: -0.06em;
  line-height: 0.8;
}

.prestige-wrap h1 em {
  color: var(--gold);
  font-style: italic;
  font-weight: 400;
}

.prestige-wrap > p {
  max-width: 560px;
  margin: 18px auto 0;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 1.15rem;
  font-style: italic;
  line-height: 1.45;
}

.prestige-outfits {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-top: 30px;
  text-align: left;
}

.prestige-outfit {
  border: 1px solid var(--line);
  background: var(--panel);
}

.prestige-outfit img {
  width: 100%;
  aspect-ratio: 3 / 3.7;
  object-fit: cover;
  object-position: 50% 18%;
  filter: saturate(0.85);
}

.prestige-outfit div {
  padding: 8px 10px;
}

.prestige-outfit strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.1rem;
  font-weight: 500;
}

.prestige-outfit span {
  display: block;
  margin-top: 2px;
  color: var(--gold);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.prestige-actions {
  display: flex;
  justify-content: center;
  gap: 9px;
  margin-top: 28px;
}

/* ---------- deck / info modal ---------- */

.deck-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.deck-entry {
  padding: 8px 9px;
  border: 1px solid var(--line);
  background: rgba(239, 230, 210, 0.02);
}

.deck-entry-top {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  align-items: baseline;
}

.deck-entry-top strong {
  color: var(--cream-2);
  font-family: var(--serif);
  font-size: 1rem;
  font-weight: 500;
  line-height: 1.1;
}

.deck-entry-top span {
  color: var(--gold);
  font-family: var(--mono);
  font-size: 8px;
}

.deck-entry p {
  margin-top: 3px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 7px;
  line-height: 1.45;
}

.deck-entry.upgraded {
  border-color: rgba(216, 177, 108, 0.33);
}

.deck-entry.upgraded .deck-entry-top strong {
  color: var(--gold);
}

.charm-list-modal {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
}

.charm-entry {
  padding: 10px;
  border: 1px solid var(--line);
  background: rgba(239, 230, 210, 0.02);
}

.charm-entry strong {
  display: block;
  color: var(--green);
  font-family: var(--serif);
  font-size: 1.15rem;
  font-weight: 500;
}

.charm-entry span {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
}

/* ---------- toast ---------- */

.notice-toast {
  position: fixed;
  z-index: 70;
  right: 20px;
  bottom: 22px;
  max-width: 340px;
  padding: 10px 14px;
  border: 1px solid var(--line-strong);
  color: var(--cream-2);
  background: rgba(20, 17, 21, 0.95);
  box-shadow: var(--shadow);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
  line-height: 1.5;
  animation: rise-in 220ms ease both;
