    const raw = localStorage.getItem(SAVE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

const game = new Game(loadMeta());
const ui = new UI(game);
game.onChange = () => ui.render();
ui.mount();

