/* ---------- run bar ---------- */

.run-bar {
  position: sticky;
  z-index: 30;
  top: 0;
  display: flex;
  align-items: center;
  gap: 18px;
  min-height: 66px;
  padding: 9px clamp(14px, 3vw, 42px);
  border-bottom: 1px solid var(--line);
  background: rgba(11, 9, 11, 0.9);
  backdrop-filter: blur(14px);
}

.run-brand {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.run-brand:hover {
  color: var(--cream);
}

.run-brand .brand-mark {
  width: 27px;
  height: 27px;
  font-size: 13px;
}

.run-identity {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding-left: 15px;
  border-left: 1px solid var(--line);
}

.run-identity-img {
  width: 38px;
  height: 46px;
  flex: 0 0 auto;
  border: 1px solid var(--line-strong);
  object-fit: cover;
  object-position: 50% 20%;
  filter: saturate(0.8);
}

.run-identity-copy {
  min-width: 0;
}

.run-identity-copy span {
  display: block;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.run-identity-copy strong {
  display: block;
  overflow: hidden;
  max-width: 170px;
  font-family: var(--serif);
  font-size: 1.2rem;
  font-weight: 500;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.run-vitals {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-left: auto;
}

.run-vital {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 52px;
}

.run-vital span {
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.run-vital strong {
  color: var(--cream-2);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.run-vital strong.hp {
  color: var(--red);
}

.run-vital strong.gold {
  color: var(--gold);
}

.run-hp-bar {
  display: flex;
  width: 132px;
