.title-screen::before {
  content: "";
  position: absolute;
  top: 13%;
  left: 50%;
  width: min(62vw, 900px);
  aspect-ratio: 1;
  border: 1px solid rgba(239, 230, 210, 0.05);
  transform: translateX(-50%) rotate(45deg);
  pointer-events: none;
}

.title-screen::after {
  content: "";
  position: absolute;
  top: 18%;
  left: 50%;
  width: min(45vw, 680px);
  aspect-ratio: 1;
  border: 1px solid rgba(239, 230, 210, 0.035);
  transform: translateX(-50%) rotate(45deg);
  pointer-events: none;
